// Cyrus unified asset catalog (R1): ONE shape for every library asset, whatever its kind (sound, texture, later
// models) and wherever it comes from (built-in libraries, the customer's uploads and other projects, the current
// project). Pure types, client-safe. MASTER-PLAN "Asset Library (owner requirement, 2026-10-10)".
import type { SlotKey } from "../texture-library/compile";

export const LIBRARY_KINDS = ["sound", "texture", "model"] as const;
export type LibraryKind = (typeof LIBRARY_KINDS)[number];
/** builtin = shipped by Cyrus (owner/Cyrus libraries); user = the customer's uploads and assets of their OTHER projects; project = already in the current project. */
export const LIBRARY_SOURCES = ["builtin", "user", "project"] as const;
export type LibrarySource = (typeof LIBRARY_SOURCES)[number];

/** Licence / provenance ledger. `original` is true only for art authored from scratch by Cyrus (never asserted for uploads or third-party files). */
export type LibraryLedger = { provenance: string; licence: string | null; licenceStatus: string; author: string | null; original: boolean; derivedFrom: string | null };

/** How a client previews the asset without the catalog shipping bytes. */
export type PreviewRef =
  | { type: "texture-template"; itemId: string; templateId: string; ramps: Partial<Record<SlotKey, string>>; dna: string; pngSha256: string }
  | { type: "texture-asset"; assetId: string; sha256: string; mime: string | null }
  | { type: "sound-render-host"; libraryId: string; sha256: string }
  | { type: "sound-asset"; assetId: string; sha256: string }
  | { type: "none" };

export type DescriptorValue = string | number | boolean | null;
export type LibraryAsset = {
  kind: LibraryKind;
  source: LibrarySource;
  /** unique within (kind, source); `ref` is globally unique */
  id: string;
  ref: string;
  name: string;
  category: string;
  subcategory: string | null;
  useCases: string[];
  tags: string[];
  descriptors: Record<string, DescriptorValue>;
  ledger: LibraryLedger;
  preview: PreviewRef;
  /** user/project assets: the project that holds it */
  projectId: string | null;
};
export const assetRef = (kind: LibraryKind, source: LibrarySource, id: string) => `${kind}/${source}/${id}`;

export type ProviderContext = { userId: string; projectId: string | null };
export interface LibraryProvider {
  readonly kind: LibraryKind;
  /** the sources this provider can return (the gate decides per source) */
  readonly sources: readonly LibrarySource[];
  list(ctx: ProviderContext, allowed: ReadonlySet<LibrarySource>): Promise<readonly LibraryAsset[]>;
}
// The catalog service: plan gate + providers + unified search, behind injectable host seams (plan lookup, asset
// store). Cyrus reaches Nxeon ONLY through `CatalogDeps.planOf` (today: lib/cyrus/tokens/access tierOf, wired by
// the route that will call this) and the UserAssetStore. Server code calls it per request; nothing here caches
// across users.
import { canBrowse, type BrowseDecision } from "./gate";
import { searchAssets, similarAssets, type UnifiedQuery, type UnifiedResult } from "./search";
import { LIBRARY_KINDS, LIBRARY_SOURCES, type LibraryAsset, type LibraryKind, type LibraryProvider, type LibrarySource, type ProviderContext } from "./types";

export type CatalogDeps = {
  providers: readonly LibraryProvider[];
  /** the viewer's raw plan (any spelling asset-gate understands); throw or return null when unknown -> fail closed */
  planOf: (userId: string) => Promise<unknown>;
};
export type BrowseRequest = { userId: string | null; projectId?: string | null; query?: UnifiedQuery };
export type Denial = { kind: LibraryKind; source: LibrarySource; code: Exclude<BrowseDecision, { ok: true }>["code"]; reason: string; needs?: string };
export type BrowseResponse = UnifiedResult & { denied: Denial[] };

async function visible(deps: CatalogDeps, req: BrowseRequest, kinds: readonly LibraryKind[]): Promise<{ assets: LibraryAsset[]; denied: Denial[] }> {
  const denied: Denial[] = [];
  if (!req.userId) {
    for (const kind of kinds) denied.push({ kind, source: "builtin", code: "sign_in", reason: "Sign in to browse the asset library." });
    return { assets: [], denied };
  }
  let plan: unknown = null;
  try { plan = await deps.planOf(req.userId); } catch { plan = null; } // unknown plan: fail closed (project assets stay visible)
  const viewer = { signedIn: true, plan };
  const ctx: ProviderContext = { userId: req.userId, projectId: req.projectId ?? null };
  const assets: LibraryAsset[] = [];
  for (const kind of kinds) {
    const allowed = new Set<LibrarySource>();
    for (const source of LIBRARY_SOURCES) {
      if (source === "project" && !ctx.projectId) continue;
      if (!deps.providers.some((p) => p.kind === kind && p.sources.includes(source))) continue;
      const d = canBrowse(viewer, kind, source);
      if (d.ok) allowed.add(source);
      else denied.push({ kind, source, code: d.code, reason: d.reason, ...(d.needs ? { needs: d.needs } : {}) });
    }
    if (!allowed.size) continue;
    for (const p of deps.providers) if (p.kind === kind) for (const a of await p.list(ctx, allowed)) if (allowed.has(a.source)) assets.push(a);
  }
  return { assets, denied };
}

/** Browse / search the catalog as this viewer. Gated sources are left out and listed in `denied` (for an upgrade hint). */
export async function browseLibrary(deps: CatalogDeps, req: BrowseRequest): Promise<BrowseResponse> {
  const q = req.query ?? {};
  const kinds = (q.kinds?.length ? q.kinds : LIBRARY_KINDS).filter((k) => (LIBRARY_KINDS as readonly string[]).includes(k));
  const { assets, denied } = await visible(deps, req, kinds);
  return { ...searchAssets(assets, q), denied };
}

/** "Similar to" within what the viewer may see. */
export async function similarInLibrary(deps: CatalogDeps, req: BrowseRequest & { ref: string; limit?: number }): Promise<LibraryAsset[]> {
  const kind = req.ref.split("/")[0] as LibraryKind;
  if (!(LIBRARY_KINDS as readonly string[]).includes(kind)) return [];
  const { assets } = await visible(deps, req, [kind]);
  return similarAssets(req.ref, assets, req.limit);
}
// Unified search over LibraryAsset (pure, client-safe): one query across sounds, textures and (later) models, with
// both taxonomies' synonym tables (sound taxonomy.json + texture taxonomy.json), ranking
//   exact tag (5; 4 via a synonym) > use case / category / subcategory / kind (3) > tag prefix (2) > name words (1),
//   +0.5 each when the word is the asset's subcategory / its primary material,
// where EVERY query word must match something; filters, facets, pagination and `similarTo`.
// Same rules as lib/cyrus/sound/library-search.ts (which stays the sound-only API the Sound Studio already uses).
import { TAXONOMY as SOUND_TAX, categoryLabel } from "../sound/classify";
import { TEXTURE_TAXONOMY as TEX_TAX } from "../texture-library/compile";
import type { DescriptorValue, LibraryAsset, LibraryKind, LibrarySource } from "./types";

export type UnifiedFilters = {
  kinds?: LibraryKind[]; sources?: LibrarySource[]; category?: string | string[]; subcategory?: string | string[]; useCase?: string | string[];
  tags?: string[]; descriptors?: Record<string, DescriptorValue[]>;
};
export type UnifiedQuery = UnifiedFilters & { text?: string; limit?: number; offset?: number };
export const FACET_DESCRIPTORS = ["size", "transparency", "tileable", "material", "durationClass", "intensity", "pitchBand", "quality", "moderation"] as const;
export type UnifiedFacets = { kind: Record<string, number>; source: Record<string, number>; category: Record<string, number>; subcategory: Record<string, number>; useCase: Record<string, number>; descriptors: Record<string, Record<string, number>> };
export type UnifiedResult = { total: number; items: LibraryAsset[]; facets: UnifiedFacets; expanded: string[][] };

const STOP = new Set([...SOUND_TAX.stopWords, ...TEX_TAX.stopWords]);
const canon = (w: string) => TEX_TAX.synonyms[w] ?? SOUND_TAX.synonyms[w] ?? w;
export const queryWords = (text: string) => text.toLowerCase().replace(/['’]/g, "").split(/[^a-z0-9]+/).filter((w) => w && !STOP.has(w));

/** A query word, its canonical forms in both taxonomies, and both query-synonym tables (one level + nested aliases). */
export function expandTerm(w: string): string[] {
  const out = new Set<string>([w]);
  for (const c of [TEX_TAX.synonyms[w], SOUND_TAX.synonyms[w]]) if (c) out.add(c);
  for (const x of [...out]) for (const table of [TEX_TAX.querySynonyms, SOUND_TAX.querySynonyms]) {
    for (const s of table[x] ?? []) { out.add(s); for (const t of TEX_TAX.querySynonyms[s] ?? []) out.add(t); for (const t of SOUND_TAX.querySynonyms[s] ?? []) out.add(t); }
  }
  return [...out];
}

const arr = <T>(v: T | T[] | undefined) => (v == null ? null : Array.isArray(v) ? v : [v]);
function matches(a: LibraryAsset, f: UnifiedFilters): boolean {
  if (f.kinds && !f.kinds.includes(a.kind)) return false;
  if (f.sources && !f.sources.includes(a.source)) return false;
  const cats = arr(f.category), subs = arr(f.subcategory), ucs = arr(f.useCase);
  if (cats && !cats.includes(a.category)) return false;
  if (subs && !(a.subcategory && subs.includes(a.subcategory))) return false;
  if (ucs && !ucs.some((u) => a.useCases.includes(u))) return false;
  if (f.tags && f.tags.some((t) => !a.tags.includes(t.toLowerCase()))) return false;
  if (f.descriptors) for (const [k, vs] of Object.entries(f.descriptors)) if (!vs.includes(a.descriptors[k] ?? null)) return false;
  return true;
}

const label = (a: LibraryAsset) => (a.kind === "sound" ? categoryLabel(a.category) : TEX_TAX.categories.find((c) => c.id === a.category)?.label ?? a.category).toLowerCase();

function scoreWord(a: LibraryAsset, word: string, terms: string[], nameWords: string[]): number {
  let best = 0;
  const self = new Set([word, canon(word)]);
  for (const t of terms) {
    if (a.tags.includes(t)) best = Math.max(best, self.has(t) ? 5 : 4);
    else if (a.useCases.includes(t) || a.category === t || a.subcategory === t || label(a) === t || a.kind === t) best = Math.max(best, 3);
    else if (t.length >= 3 && a.tags.some((x) => x.startsWith(t))) best = Math.max(best, 2);
    else if (t.length >= 3 && nameWords.some((n) => n.includes(t))) best = Math.max(best, 1);
    if (best === 5) break;
  }
  // tie-break inside a score: the word names what the asset IS (its subcategory or primary material), not only
  // something it carries (a stone-family ramp on a brick's mortar, an iron rim on a shield)
  if (best && terms.some((t) => a.subcategory === t)) best += 0.5;
  if (best && terms.some((t) => a.descriptors.material === t)) best += 0.5;
  return best;
}

const SOURCE_RANK: Record<LibrarySource, number> = { project: 0, user: 1, builtin: 2 };

export function searchAssets(assets: readonly LibraryAsset[], q: UnifiedQuery = {}): UnifiedResult {
  const words = queryWords(q.text ?? "");
  const expanded = words.map(expandTerm);
  const scored: { a: LibraryAsset; score: number }[] = [];
  for (const a of assets) {
    if (!matches(a, q)) continue;
    const nameWords = queryWords(`${a.name} ${a.id}`);
    let score = 0, miss = false;
    for (const [i, w] of words.entries()) { const v = scoreWord(a, w, expanded[i], nameWords); if (!v) { miss = true; break; } score += v; }
    if (!miss) scored.push({ a, score });
  }
  scored.sort((x, y) => y.score - x.score || SOURCE_RANK[x.a.source] - SOURCE_RANK[y.a.source] || (x.a.ref < y.a.ref ? -1 : 1));
  const facets: UnifiedFacets = { kind: {}, source: {}, category: {}, subcategory: {}, useCase: {}, descriptors: {} };
  const inc = (m: Record<string, number>, k: string) => { m[k] = (m[k] ?? 0) + 1; };
  for (const { a } of scored) {
    inc(facets.kind, a.kind); inc(facets.source, a.source); inc(facets.category, a.category);
    if (a.subcategory) inc(facets.subcategory, a.subcategory);
    for (const u of a.useCases) inc(facets.useCase, u);
    for (const k of FACET_DESCRIPTORS) if (a.descriptors[k] !== undefined) inc((facets.descriptors[k] ??= {}), String(a.descriptors[k]));
  }
  const off = Math.max(0, Math.floor(q.offset ?? 0)), lim = Math.min(200, Math.max(1, Math.floor(q.limit ?? 50)));
  return { total: scored.length, items: scored.slice(off, off + lim).map((x) => x.a), facets, expanded };
}

/** Assets like this one (same kind): category, subcategory, shared use cases, tags and descriptor values. */
export function similarAssets(ref: string, assets: readonly LibraryAsset[], limit = 10): LibraryAsset[] {
  const me = assets.find((a) => a.ref === ref);
  if (!me) return [];
  return assets.filter((a) => a.ref !== ref && a.kind === me.kind).map((a) => {
    let s = 0;
    if (a.category === me.category) s += 4;
    if (a.subcategory && a.subcategory === me.subcategory) s += 2;
    s += 2 * a.useCases.filter((u) => me.useCases.includes(u)).length;
    s += Math.min(4, a.tags.filter((t) => me.tags.includes(t)).length);
    for (const k of FACET_DESCRIPTORS) if (me.descriptors[k] != null && a.descriptors[k] === me.descriptors[k]) s += 1;
    if (a.kind === "texture" && a.descriptors.template === me.descriptors.template) s -= 3; // prefer other shapes over recolours
    return { a, s };
  }).filter((x) => x.s >= 5).sort((x, y) => y.s - x.s || (x.a.ref < y.a.ref ? -1 : 1)).slice(0, limit).map((x) => x.a);
}
// Built-in catalog providers (pure, client-safe): the owner's sound library and the Cyrus texture templates,
// mapped into LibraryAsset. User/project assets come from ./user-assets.ts (an injected store).
import { librarySounds, type LibrarySound } from "../sound/library";
import { libraryTextures, type TextureLibraryItem } from "../texture-library/library";
import { assetRef, type LibraryAsset, type LibraryProvider } from "./types";

export function soundAsset(s: LibrarySound): LibraryAsset {
  const d = s.descriptors;
  return {
    kind: "sound", source: "builtin", id: s.id, ref: assetRef("sound", "builtin", s.id), name: s.prefix ? `${s.prefix} (${s.id})` : s.id,
    category: s.category, subcategory: null, useCases: [...s.useCases], tags: [...s.tags],
    descriptors: { durationClass: d.durationClass, intensity: d.intensity, pitchBand: d.pitchBand, character: d.character, loopable: d.loopable, channels: d.channels, duration: s.duration },
    ledger: { provenance: s.ledger.provenance, licence: null, licenceStatus: s.ledger.licenceStatus, author: null, original: false, derivedFrom: null },
    // the audio stays on the render host; the file name is not exposed to browsers
    preview: { type: "sound-render-host", libraryId: s.id, sha256: s.sha256 },
    projectId: null,
  };
}

export function textureAsset(t: TextureLibraryItem): LibraryAsset {
  const ramps = Object.fromEntries(Object.entries(t.ramps).filter(([, v]) => v)) as Record<string, string>;
  return {
    kind: "texture", source: "builtin", id: t.id, ref: assetRef("texture", "builtin", t.id), name: t.name,
    category: t.category, subcategory: t.sub, useCases: [...t.useCases], tags: [...t.tags],
    descriptors: { ...t.descriptors, template: t.templateId, quality: t.quality.verdict },
    ledger: { provenance: t.ledger.provenance, licence: t.ledger.licence, licenceStatus: t.ledger.licenceStatus, author: t.ledger.author, original: t.ledger.original, derivedFrom: t.ledger.derivedFrom },
    preview: { type: "texture-template", itemId: t.id, templateId: t.templateId, ramps, dna: t.dna, pngSha256: t.pngSha256 },
    projectId: null,
  };
}

let soundCache: LibraryAsset[] | null = null;
let textureCache: LibraryAsset[] | null = null;
export const builtinSoundAssets = (): readonly LibraryAsset[] => (soundCache ??= librarySounds().map(soundAsset));
export const builtinTextureAssets = (): readonly LibraryAsset[] => (textureCache ??= libraryTextures().map(textureAsset));

export const SoundLibraryProvider: LibraryProvider = {
  kind: "sound", sources: ["builtin"],
  list: async (_ctx, allowed) => (allowed.has("builtin") ? builtinSoundAssets() : []),
};
export const TextureLibraryProvider: LibraryProvider = {
  kind: "texture", sources: ["builtin"],
  list: async (_ctx, allowed) => (allowed.has("builtin") ? builtinTextureAssets() : []),
};
// Browse gate for the asset catalog (pure, client-safe; the server calls it again on every request).
// Owner rules (MASTER-PLAN section 2 + Asset Library): browsing a library follows the STUDIO gate of its kind:
//   sound   -> Saka and the top plan        texture / model -> the top plan only        free / Katara -> none
// It is the plan-tier rule of lib/cyrus/engine-core/asset-gate.ts (`canAsset(plan, kind, "create")`, because picking
// from a library puts new content into a project); it does NOT spend or check generation tokens (no generate gate).
// Fail closed: not signed in or an unknown plan denies. Assets ALREADY IN THE CURRENT PROJECT (source "project")
// are never gated for a signed-in owner: keeping / installing / rebuilding them is never plan-gated.
import { canAsset, type AssetDecision } from "../engine-core/asset-gate";
import type { LibraryKind, LibrarySource } from "./types";

export type BrowseViewer = { signedIn: boolean; plan: unknown };
export type BrowseDecision = { ok: true } | { ok: false; code: "sign_in" | "asset_locked" | "plan_unknown" | "bad_request"; reason: string; needs?: string };

export function canBrowse(viewer: BrowseViewer, kind: LibraryKind, source: LibrarySource): BrowseDecision {
  if (!viewer.signedIn) return { ok: false, code: "sign_in", reason: "Sign in to browse the asset library." };
  if (source === "project") return { ok: true };
  const d: AssetDecision = canAsset(viewer.plan, kind, "create");
  if (d.ok) return { ok: true };
  return { ok: false, code: d.code, reason: d.reason.replace("Creating or editing", "Browsing and using"), ...(d.needs ? { needs: d.needs } : {}) };
}

// Canonical 3D asset record: glTF 2.0 geometry + a Cyrus sidecar manifest (research H-3d-games.md, section 3).
// The manifest carries what glTF cannot: provenance, the LEGAL CLASS, per-channel lossless layers and units.
// Channels are stored separately; packing into an engine's channels happens only at export (adapter's job).
// Pure, client-safe, Zod-validated; every failure is a structured issue, never a throw.
import { z } from "zod";
import { CHANNEL_ROLES, type ColorSpace } from "../adapters/asset-profile";
import { isSafeProjectPath } from "../engine-core/revisions";

export const ASSET_MANIFEST_SCHEMA_VERSION = 1 as const;

/** user-original / ai-generated-for-user / platform-library (Nxeon-owned or CC0 only) / third-party-licensed / game-derived. */
export const LEGAL_CLASSES = ["user-original", "ai-generated-for-user", "platform-library", "third-party-licensed", "game-derived"] as const;
export type LegalClass = (typeof LEGAL_CLASSES)[number];

export const SHA256_RE = /^[0-9a-f]{64}$/;
const sha = z.string().regex(SHA256_RE, "sha256 as 64 lowercase hex");
const safePath = z.string().refine((p) => isSafeProjectPath(p), "unsafe path");

const ChannelZ = z.object({
  role: z.enum(CHANNEL_ROLES),
  path: safePath,
  sha256: sha,
  width: z.number().int().min(1).max(16384),
  height: z.number().int().min(1).max(16384),
  colorSpace: z.enum(["srgb", "linear"]),
}).strict();

const ManifestZ = z.object({
  schemaVersion: z.literal(ASSET_MANIFEST_SCHEMA_VERSION),
  assetId: z.string().regex(/^[a-z][a-z0-9_]{0,47}$/),
  kind: z.enum(["model", "texture-set"]),
  game: z.string().regex(/^[a-z][a-z0-9-]{1,31}$/).optional(),
  units: z.literal("m"),
  upAxis: z.literal("+Y"),
  geometry: z.object({ path: safePath, sha256: sha, uvSets: z.number().int().min(0).max(8).default(1) }).strict().optional(),
  channels: z.array(ChannelZ).max(16).default([]),
  legalClass: z.enum(LEGAL_CLASSES),
  /** project = kept with the project; job = deleted when the job ends (the only legal option for game-derived content). */
  retention: z.enum(["project", "job"]).default("project"),
  provenance: z.object({
    source: z.enum(["user", "ai", "library", "import", "upload", "template"]),
    note: z.string().max(300).optional(),
    /** sha256 of the inputs this asset was derived from (a retexture lists the base it was painted on). */
    derivedFrom: z.array(sha).max(32).default([]),
  }).strict(),
}).strict();

export type AssetManifest = z.infer<typeof ManifestZ>;
export type ManifestIssue = { path: string; code: string; message: string };
export type ManifestParse = { ok: true; manifest: AssetManifest } | { ok: false; errors: ManifestIssue[] };

/** What the ledger allows for a class. The rule: game-derived content never outlives its job, never enters a library, never ships. */
export type LedgerRules = { storeBeyondJob: boolean; addToLibrary: boolean; redistribute: boolean; deliverable: "full" | "delta-only" };
export function ledgerRules(c: LegalClass): LedgerRules {
  switch (c) {
    case "game-derived": return { storeBeyondJob: false, addToLibrary: false, redistribute: false, deliverable: "delta-only" };
    case "third-party-licensed": return { storeBeyondJob: true, addToLibrary: false, redistribute: false, deliverable: "full" };
    // Owner decision 2026-10-10: assets made in Cyrus contribute to the community library automatically (no opt-in).
    default: return { storeBeyondJob: true, addToLibrary: true, redistribute: true, deliverable: "full" };
  }
}

/**
 * Whether a manifest is eligible for automatic contribution to the community library. Eligible = made inside Cyrus
 * (user-original authored in a studio, ai-generated-for-user) or already Nxeon's own, and not derived from any other bytes.
 * Never: game-derived, third-party-licensed, imported/uploaded/template content, or anything with a derivedFrom entry. Eligible is not published: the
 * content filters (trademark, real-weapon, adult content) and the terms-of-service grant still gate publication.
 */
export function libraryEligible(m: Pick<AssetManifest, "legalClass" | "provenance">): boolean {
  if (!ledgerRules(m.legalClass).addToLibrary) return false;
  // Only content authored inside Cyrus from nothing outside it: no imports/uploads/templates, and nothing derived from other bytes
  // (a livery painted on someone's template lists that template in derivedFrom, so it is never auto-contributed).
  if (!["user", "ai", "library"].includes(m.provenance.source)) return false;
  return m.provenance.derivedFrom.length === 0;
}

export function validateAssetManifest(raw: unknown): ManifestParse {
  const r = ManifestZ.safeParse(raw);
  if (!r.success) return { ok: false, errors: r.error.issues.map((i) => ({ path: i.path.join(".") || "manifest", code: "invalid", message: i.message })) };
  const m = r.data;
  const errors: ManifestIssue[] = [];
  const add = (path: string, code: string, message: string) => errors.push({ path, code, message });
  const seen = new Set<string>();
  m.channels.forEach((c, i) => {
    if (seen.has(c.role)) add(`channels.${i}.role`, "duplicate_role", `channel role ${c.role} appears twice`);
    seen.add(c.role);
    const want: ColorSpace | null = c.role === "albedo" || c.role === "emissive" ? "srgb" : c.role === "normal" || c.role === "roughness" || c.role === "metallic" || c.role === "ao" || c.role === "height" ? "linear" : null;
    if (want && c.colorSpace !== want) add(`channels.${i}.colorSpace`, "wrong_color_space", `${c.role} must be ${want}`);
  });
  if (m.kind === "model" && !m.geometry) add("geometry", "geometry_required", "a model needs a geometry file");
  if (m.kind === "texture-set" && m.channels.length === 0) add("channels", "channels_required", "a texture set needs at least one channel");
  if (m.legalClass === "game-derived") {
    if (m.retention !== "job") add("retention", "game_derived_must_be_job", "game-derived assets are kept only for the job and must use retention \"job\"");
    if (!m.game) add("game", "game_required", "a game-derived asset must name its game");
    if (m.provenance.derivedFrom.length === 0) add("provenance.derivedFrom", "derived_from_required", "list the base content hashes so a delta can be computed");
  }
  if (m.legalClass === "platform-library" && m.provenance.source !== "library") add("provenance.source", "library_source", "platform-library assets come from the library");
  return errors.length ? { ok: false, errors } : { ok: true, manifest: m };
}
// Asset profile: what ONE game's adapter declares about 3D/texture assets (MULTIGAME research H-3d-games.md, section 3).
// Interfaces + a validator only. Nothing here changes behaviour; Minecraft is the first filled-in profile, every
// other game declares its own when its adapter is written. Pure, client-safe, no Nxeon imports.
import type { AdapterMaturity } from "./types";

/** How custom assets reach players. Only the first and the two workshop forms need no player action. */
export const DELIVERY_STRATEGIES = ["server-streamed", "workshop-user-publishes", "workshop-platform-publishes", "client-manual", "none"] as const;
export type DeliveryStrategy = (typeof DELIVERY_STRATEGIES)[number];

/** Which kind of worker a job needs. linux-cpu = node-2 style builds; windows-tools = Windows-only game tools; gpu = image/3D models. */
export const WORKER_CLASSES = ["linux-cpu", "windows-tools", "gpu"] as const;
export type WorkerClass = (typeof WORKER_CLASSES)[number];

/** none = nothing from the game needed; user-supplied = the user brings templates/base files; platform-licensed = Nxeon holds a licence. */
export const REQUIRED_GAME_FILES = ["none", "user-supplied", "platform-licensed"] as const;
export type RequiredGameFiles = (typeof REQUIRED_GAME_FILES)[number];

/** Channel roles of a texture set. Stored as separate lossless layers; packed into engine channels only at export. */
export const CHANNEL_ROLES = ["albedo", "normal", "roughness", "metallic", "ao", "emissive", "height", "opacity", "mask"] as const;
export type ChannelRole = (typeof CHANNEL_ROLES)[number];

export type ColorSpace = "srgb" | "linear";
export type NormalConvention = "opengl" | "directx" | "none";
export type TextureCompression = "png" | "bc1" | "bc3" | "bc5" | "bc7" | "ktx2";
export type EngineFamily = "minecraft-java" | "unreal" | "unity" | "source" | "rage" | "creation" | "hytale" | "other";

/** Where a role lands in the game's packed texture: a file name pattern and the channel(s) of it. */
export type ChannelTarget = { file: string; channels: "rgb" | "rgba" | "r" | "g" | "b" | "a" };

/** What the game owner's published terms say about hosted modding. `reviewed` is false until a human read the page. */
export type LegalPolicy = {
  policyUrl: string | null;
  /** true / false only when a reviewer read the source; otherwise "unknown" (the honest default). */
  commercialOk: boolean | "unknown";
  aiOk: boolean | "unknown";
  /** A game's own assets are never redistributed, so this is the literal false. */
  redistributeBase: false;
  monetisationRule?: string;
  attestationRequired: boolean;
  /** ISO date the policy page was last read, or null. */
  retrievedAt: string | null;
  reviewed: boolean;
};

export type AssetProfile = {
  game: string;
  engineFamily: EngineFamily;
  meshFormats: readonly string[];
  textureFormats: readonly string[];
  compression: readonly TextureCompression[];
  channelMap: Readonly<Partial<Record<ChannelRole, ChannelTarget>>>;
  normalConvention: NormalConvention;
  colorSpace: Readonly<Partial<Record<ChannelRole, ColorSpace>>>;
  /** Largest texture edge in pixels the game/adapter accepts. */
  maxTextureRes: number;
  /** reuse-template = the user's UV layout is kept; new = Cyrus may unwrap; none = the game has no UVs to manage. */
  uvRules: "reuse-template" | "new" | "none";
  skeletonPolicy: "reuse" | "own" | "none" | "forbidden";
  packaging: string;
  delivery: DeliveryStrategy;
  workerClass: WorkerClass;
  requiredGameFiles: RequiredGameFiles;
  legal: LegalPolicy;
  validators: readonly string[];
  previewShader: string;
  maturity: AdapterMaturity;
};

export type ProfileIssue = { path: string; code: string; message: string };

/** Cheap structural rules a profile must satisfy; returns issues, never throws. */
export function validateAssetProfile(p: AssetProfile): ProfileIssue[] {
  const out: ProfileIssue[] = [];
  const add = (path: string, code: string, message: string) => out.push({ path, code, message });
  if (!DELIVERY_STRATEGIES.includes(p.delivery)) add("delivery", "bad_delivery", `unknown delivery strategy ${String(p.delivery)}`);
  if (!WORKER_CLASSES.includes(p.workerClass)) add("workerClass", "bad_worker_class", `unknown worker class ${String(p.workerClass)}`);
  if (!REQUIRED_GAME_FILES.includes(p.requiredGameFiles)) add("requiredGameFiles", "bad_required_files", `unknown value ${String(p.requiredGameFiles)}`);
  if ((p.legal.redistributeBase as unknown) !== false) add("legal.redistributeBase", "must_be_false", "a game's base assets are never redistributed");
  if ((p.legal.commercialOk === true || p.legal.aiOk === true) && !p.legal.reviewed) add("legal.reviewed", "unreviewed_claim", "commercialOk/aiOk can only be true after a human reviewed the policy");
  if (p.legal.reviewed && (!p.legal.policyUrl || !p.legal.retrievedAt)) add("legal.policyUrl", "missing_source", "a reviewed policy needs its url and retrieval date");
  if (p.maturity === "stable" && !p.legal.reviewed) add("maturity", "stable_needs_legal", "a stable adapter needs a reviewed legal policy");
  if (p.delivery === "client-manual" && p.maturity === "stable") add("delivery", "manual_not_stable", "assets players must install by hand cannot be a stable path");
  if (p.requiredGameFiles !== "none" && p.legal.attestationRequired !== true) add("legal.attestationRequired", "attestation_needed", "user-supplied or licensed game files need an ownership attestation");
  if (p.workerClass === "windows-tools" && p.requiredGameFiles === "platform-licensed") add("requiredGameFiles", "windows_licensed", "a Windows worker must not hold a platform-licensed game install without a separate legal review");
  if (!(p.maxTextureRes >= 16 && p.maxTextureRes <= 16384)) add("maxTextureRes", "bad_res", "maxTextureRes must be between 16 and 16384");
  if (p.channelMap.albedo && p.colorSpace.albedo && p.colorSpace.albedo !== "srgb") add("colorSpace.albedo", "albedo_srgb", "albedo is stored in sRGB");
  if (p.colorSpace.normal && p.colorSpace.normal !== "linear") add("colorSpace.normal", "normal_linear", "normal maps are linear data");
  if (p.channelMap.normal && p.normalConvention === "none") add("normalConvention", "normal_needs_convention", "a normal channel needs opengl or directx");
  for (const role of Object.keys(p.channelMap)) if (!CHANNEL_ROLES.includes(role as ChannelRole)) add(`channelMap.${role}`, "bad_role", `unknown channel role ${role}`);
  return out;
}
// Cyrus engine core: the plan-tier gate for custom assets (MASTER-PLAN section 2, owner decisions).
//   free, katara -> no asset studios, no asset generation
//   saka         -> SOUND (Sound Studio + Sound Library)
//   all          -> SOUND + TEXTURE (the top plan; it includes the Yakko model)
// Tiers are cumulative. The gate applies only to CREATING or EDITING asset content (a studio, a library pick, an
// upload, or Cyrus generating it automatically inside a build). Keeping, installing, rebuilding unchanged,
// exporting, importing your own mod and composing Mod Packs are NEVER gated. An unknown plan or token state
// denies creation (fail closed) but never denies keep/install/export.
// Pure + client-safe; the server must call it again on every request (the UI check is only a hint).
import type { AssetKind, AssetSource, ModSpec } from "./spec";
import { ASSET_KINDS } from "./spec";

export const ASSET_PLANS = ["free", "katara", "saka", "all"] as const;
export type AssetPlan = (typeof ASSET_PLANS)[number];
const RANK: Record<AssetPlan, number> = { free: 0, katara: 1, saka: 2, all: 3 };
export const PLAN_LABEL: Record<AssetPlan, string> = { free: "Free", katara: "Katara", saka: "Saka", all: "All models" };

/**
 * THE one place that reconciles plan spellings. The token economy calls the top plan `all`
 * (lib/cyrus/tokens/config.ts TOKEN_TIERS); the UI and the model list call it after its top model, Yakko.
 * Anything else (null, a typo, a future plan) is unknown -> null, and callers fail closed.
 */
export function normalizePlan(raw: unknown): AssetPlan | null {
  if (typeof raw !== "string") return null;
  const v = raw.trim().toLowerCase();
  if (v === "all" || v === "yakko" || v === "all models") return "all";
  if (v === "free" || v === "katara" || v === "saka") return v;
  return null;
}

/** Plan from a token state (lib/cyrus/tokens/view.ts TokenState) or anything with a `tier`. Missing state -> null (unknown). */
export const planFromTokenState = (state: { tier?: unknown } | null | undefined): AssetPlan | null => normalizePlan(state?.tier);

/**
 * Cheapest plan that may create/edit each kind. `model` and `ui` are visual assets drawn with the texture tools,
 * so they follow the Texture Studio (top plan).
 */
export const ASSET_MIN_PLAN: Readonly<Record<AssetKind, AssetPlan>> = { sound: "saka", texture: "all", model: "all", ui: "all" };

export const ASSET_OPS = ["create", "edit", "keep", "install", "export", "rebuild", "import", "compose"] as const;
export type AssetOp = (typeof ASSET_OPS)[number];
export const GATED_OPS: readonly AssetOp[] = ["create", "edit"];

export type AssetDecision =
  | { ok: true }
  | { ok: false; code: "asset_locked" | "plan_unknown" | "bad_request"; reason: string; needs?: AssetPlan };

const KIND_WORD: Record<AssetKind, string> = { sound: "custom sounds", texture: "custom textures", model: "custom models", ui: "custom menu and HUD art" };

export function canAsset(plan: unknown, kind: AssetKind, op: AssetOp): AssetDecision {
  if (!(ASSET_OPS as readonly string[]).includes(op)) return { ok: false, code: "bad_request", reason: `unknown asset operation ${String(op)}` };
  if (!GATED_OPS.includes(op)) return { ok: true }; // keep / install / export / rebuild / import / compose: never gated
  if (!(ASSET_KINDS as readonly string[]).includes(kind)) return { ok: false, code: "bad_request", reason: `unknown asset kind ${String(kind)}` };
  const needs = ASSET_MIN_PLAN[kind];
  const p = normalizePlan(plan);
  if (!p) return { ok: false, code: "plan_unknown", needs, reason: `We couldn't confirm your Cyrus plan, so ${KIND_WORD[kind]} can't be created or edited right now.` };
  if (RANK[p] < RANK[needs]) return { ok: false, code: "asset_locked", needs, reason: `Creating or editing ${KIND_WORD[kind]} needs the ${PLAN_LABEL[needs]} plan or higher.` };
  return { ok: true };
}

/** What a spec asset slot asks the engine to do with asset content. */
export function assetOpForSource(source: AssetSource): AssetOp {
  switch (source) {
    case "generate": case "library": case "upload": return "create";
    case "edit": return "edit";
    case "existing": return "keep";
    case "imported": return "import";
    default: return "create"; // unknown source: treat as the gated case
  }
}

export type AssetDenial = { assetId: string; kind: AssetKind; code: "asset_locked" | "plan_unknown" | "bad_request"; reason: string; needs?: AssetPlan };

/** Every asset slot of a spec the plan may not create/edit (no changes). The build service request runs this too. */
export function gateSpecAssets(spec: Pick<ModSpec, "assets">, plan: unknown): AssetDenial[] {
  const out: AssetDenial[] = [];
  for (const a of spec.assets) {
    const d = canAsset(plan, a.kind, assetOpForSource(a.source));
    if (!d.ok) out.push({ assetId: a.id, kind: a.kind, code: d.code, reason: d.reason, ...(d.needs ? { needs: d.needs } : {}) });
  }
  return out;
}

const FALLBACK: Record<AssetKind, string> = { sound: "a vanilla sound", texture: "a vanilla look", model: "a vanilla model", ui: "plain text and standard menus" };

/**
 * Router downgrade: strip the gated asset slots instead of failing the build, with a customer-visible reason
 * per slot. Requirements stay (the mod still does what was asked, without the custom asset). Pure: returns a copy.
 */
export function downgradeSpecAssets<S extends Pick<ModSpec, "assets">>(spec: S, plan: unknown): { spec: S; removed: AssetDenial[]; notices: string[] } {
  const removed = gateSpecAssets(spec, plan);
  if (!removed.length) return { spec, removed, notices: [] };
  const drop = new Set(removed.map((r) => r.assetId));
  const notices = removed.map((r) => `${r.reason} Cyrus will build "${r.assetId}" with ${FALLBACK[r.kind]} instead.`);
  return { spec: { ...spec, assets: spec.assets.filter((a) => !drop.has(a.id)) }, removed, notices };
}
// Asset job contract: a pull-based queue with worker classes, plus a content-addressed object store.
// Interfaces first (research H-3d-games.md, decision 3): a Windows or GPU worker can plug in later without
// reworking the build service. HOST SEAM: no Nxeon imports; the host injects a real queue/store. The in-memory
// versions below exist for tests and for the first single-box lane. Pure Node (crypto only).
import { createHash } from "node:crypto";
import { WORKER_CLASSES, type WorkerClass } from "../adapters/asset-profile";

export const sha256Hex = (bytes: Uint8Array | string): string => createHash("sha256").update(bytes).digest("hex");
/** Content-addressed key: identical bytes always map to the same key, so uploads dedupe and keys never collide by name. */
export const contentKey = (bytes: Uint8Array | string): string => `sha256/${sha256Hex(bytes)}`;

export interface ObjectStore {
  /** Stores bytes and returns their content key (idempotent). */
  put(bytes: Uint8Array): Promise<string>;
  get(key: string): Promise<Uint8Array | null>;
  has(key: string): Promise<boolean>;
  delete(key: string): Promise<void>;
}

export function createMemoryObjectStore(): ObjectStore {
  const m = new Map<string, Uint8Array>();
  return {
    async put(bytes) { const k = contentKey(bytes); if (!m.has(k)) m.set(k, Uint8Array.from(bytes)); return k; },
    async get(key) { return m.get(key) ?? null; },
    async has(key) { return m.has(key); },
    async delete(key) { m.delete(key); },
  };
}

export type JobStatus = "queued" | "running" | "done" | "failed" | "expired";
export type AssetJob = {
  id: string;
  /** Free-form job kind the worker understands ("pack-ytd", "bc7-encode", "render-preview"). */
  type: string;
  workerClass: WorkerClass;
  /** Opaque tenant/project ids; the queue never reads Nxeon tables. */
  projectId: string;
  /** Content keys of the input objects. */
  inputs: readonly string[];
  /** Hard time budget; a job past it is expired, never left running. */
  timeoutMs: number;
  status: JobStatus;
  /** Content keys of the outputs once done. */
  outputs: readonly string[];
  error?: string;
  claimedBy?: string;
  claimedAt?: number;
};

export type EnqueueInput = Pick<AssetJob, "type" | "workerClass" | "projectId" | "inputs" | "timeoutMs">;

/** Pull-based: workers ask for work in the classes they serve; the queue never pushes into a worker (so a Windows guest needs no inbound port). */
export interface JobQueue {
  enqueue(job: EnqueueInput): Promise<AssetJob>;
  claim(worker: { id: string; classes: readonly WorkerClass[] }): Promise<AssetJob | null>;
  complete(id: string, workerId: string, outputs: readonly string[]): Promise<AssetJob | null>;
  fail(id: string, workerId: string, error: string): Promise<AssetJob | null>;
  /** Expire running jobs past their timeout; returns the expired jobs. */
  sweep(): Promise<AssetJob[]>;
  get(id: string): Promise<AssetJob | null>;
}

export const MAX_JOB_TIMEOUT_MS = 30 * 60 * 1000;

export function createMemoryJobQueue(now: () => number = Date.now): JobQueue {
  const jobs = new Map<string, AssetJob>();
  let seq = 0;
  return {
    async enqueue(j) {
      if (!WORKER_CLASSES.includes(j.workerClass)) throw new Error(`unknown worker class ${String(j.workerClass)}`);
      if (!(j.timeoutMs > 0 && j.timeoutMs <= MAX_JOB_TIMEOUT_MS)) throw new Error(`timeoutMs must be 1..${MAX_JOB_TIMEOUT_MS}`);
      const job: AssetJob = { id: `job_${++seq}`, ...j, status: "queued", outputs: [] };
      jobs.set(job.id, job);
      return { ...job };
    },
    async claim(w) {
      for (const j of jobs.values()) {
        if (j.status === "queued" && w.classes.includes(j.workerClass)) {
          j.status = "running"; j.claimedBy = w.id; j.claimedAt = now();
          return { ...j };
        }
      }
      return null;
    },
    async complete(id, workerId, outputs) {
      const j = jobs.get(id);
      if (!j || j.status !== "running" || j.claimedBy !== workerId) return null;
      j.status = "done"; j.outputs = [...outputs];
      return { ...j };
    },
    async fail(id, workerId, error) {
      const j = jobs.get(id);
      if (!j || j.status !== "running" || j.claimedBy !== workerId) return null;
      j.status = "failed"; j.error = error.slice(0, 500);
      return { ...j };
    },
    async sweep() {
      const out: AssetJob[] = [];
      for (const j of jobs.values()) {
        if (j.status === "running" && j.claimedAt !== undefined && now() - j.claimedAt > j.timeoutMs) { j.status = "expired"; j.error = "timeout"; out.push({ ...j }); }
      }
      return out;
    },
    async get(id) { const j = jobs.get(id); return j ? { ...j } : null; },
  };
}

