export const SOUND_QUALITY_VERSION = "sq-1";
const r2 = (v: number) => (Number.isFinite(v) ? Math.round(v * 100) / 100 : v === Infinity ? 999 : -999);

/** K-weighting coefficients (BS.1770) for any sample rate (the pyloudnorm derivation). */
function kWeight(x: Mono, fs: number): Mono {
  let K = Math.tan((Math.PI * 1681.974450955533) / fs);
  const Q1 = 0.7071752369554196, Vh = Math.pow(10, 3.999843853973347 / 20), Vb = Math.pow(Vh, 0.4996667741545416);
  let a0 = 1 + K / Q1 + K * K;
  const s1 = [(Vh + (Vb * K) / Q1 + K * K) / a0, (2 * (K * K - Vh)) / a0, (Vh - (Vb * K) / Q1 + K * K) / a0, (2 * (K * K - 1)) / a0, (1 - K / Q1 + K * K) / a0];
  K = Math.tan((Math.PI * 38.13547087602444) / fs);
  const Q2 = 0.5003270373238773;
  a0 = 1 + K / Q2 + K * K;
  const s2 = [1, -2, 1, (2 * (K * K - 1)) / a0, (1 - K / Q2 + K * K) / a0];
  return biquadRaw(biquadRaw(x, s1), s2);
}

/** Integrated loudness (LUFS) of a mono clip; -999 for digital silence. */
export function loudness(x: Mono, fs = SAMPLE_RATE): number {
  if (!x.length) return -999;
  const y = kWeight(x, fs);
  const block = Math.round(0.4 * fs), step = Math.round(0.1 * fs);
  const ms: number[] = [];
  if (y.length < block) { let s = 0; for (let i = 0; i < y.length; i++) s += y[i] * y[i]; ms.push(s / y.length); }
  else for (let a = 0; a + block <= y.length; a += step) { let s = 0; for (let i = a; i < a + block; i++) s += y[i] * y[i]; ms.push(s / block); }
  const L = (z: number) => -0.691 + 10 * Math.log10(z);
  const abs = ms.filter((z) => z > 0 && L(z) > -70);
  if (!abs.length) return -999;
  const relGate = L(abs.reduce((a, b) => a + b, 0) / abs.length) - 10;
  const gated = ms.length === 1 ? abs : abs.filter((z) => L(z) > relGate);
  return r2(L(gated.reduce((a, b) => a + b, 0) / gated.length));
}

// 4-phase, 12-tap Hann-windowed sinc interpolator for the true-peak estimate.
const TP_PHASES = (() => {
  const taps = 12, phases = 4, out: number[][] = [];
  for (let p = 0; p < phases; p++) {
    const h: number[] = [];
    for (let k = 0; k < taps; k++) {
      const t = k - taps / 2 + 1 - p / phases;
      const sinc = t === 0 ? 1 : Math.sin(Math.PI * t) / (Math.PI * t);
      const w = 0.5 + 0.5 * Math.cos((Math.PI * t) / (taps / 2));
      h.push(sinc * w);
    }
    const sum = h.reduce((a, b) => a + b, 0);
    out.push(h.map((v) => v / sum));
  }
  return out;
})();

export function truePeakDb(x: Mono): number {
  let m = 0;
  for (let i = 0; i < x.length; i++) {
    const a = Math.abs(x[i]); if (a > m) m = a;
    for (let p = 1; p < 4; p++) {
      let s = 0; const h = TP_PHASES[p];
      for (let k = 0; k < h.length; k++) { const j = i + k - 5; if (j >= 0 && j < x.length) s += x[j] * h[k]; }
      const b = Math.abs(s); if (b > m) m = b;
    }
  }
  return r2(linToDb(m));
}

export type SoundMeasure = { durationS: number; samplePeakDb: number; truePeakDb: number; lufs: number; silenceRatio: number; dcOffset: number };

export function measure(x: Mono, fs = SAMPLE_RATE): SoundMeasure {
  let peak = 0, sum = 0;
  for (let i = 0; i < x.length; i++) { const a = Math.abs(x[i]); if (a > peak) peak = a; sum += x[i]; }
  const win = Math.round(0.01 * fs), t = dbToLin(-50);
  let quiet = 0, wins = 0;
  for (let a = 0; a < x.length; a += win) {
    let s = 0; const b = Math.min(x.length, a + win);
    for (let i = a; i < b; i++) s += x[i] * x[i];
    wins++; if (Math.sqrt(s / (b - a)) < t) quiet++;
  }
  return {
    durationS: Math.round((x.length / fs) * 1000) / 1000, samplePeakDb: r2(linToDb(peak)), truePeakDb: truePeakDb(x), lufs: loudness(x, fs),
    silenceRatio: wins ? Math.round((quiet / wins) * 1000) / 1000 : 1, dcOffset: x.length ? Math.round((sum / x.length) * 1e6) / 1e6 : 0,
  };
}

/** Gain (dB) that brings a clip to the role's target loudness, never above the true-peak ceiling. */
export function normalizeGainDb(m: SoundMeasure, role: SoundRole, ceilingDbtp: number): { gainDb: number; peakLimited: boolean } {
  const want = m.lufs <= -998 ? 0 : ROLE_PROFILE[role].target - m.lufs;
  const room = ceilingDbtp - m.truePeakDb;
  return { gainDb: r2(want), peakLimited: want > room };
}

export type SoundCheck = { id: string; status: "pass" | "warn" | "fail"; value: number | string; limit: string; message: string };
export type SoundQualityReport = { version: string; verdict: "pass" | "warn" | "fail"; role: SoundRole; checks: SoundCheck[] };
export type EncodedInfo = { codec: string; channels: number; sampleRate: number };

export const TRUE_PEAK_MAX = -1;

/** The quality bar for one rendered variant (decoded from its Ogg). */
export function soundQuality(m: SoundMeasure, enc: EncodedInfo, role: SoundRole): SoundQualityReport {
  const prof = ROLE_PROFILE[role];
  const checks: SoundCheck[] = [];
  checks.push({ id: "format", status: enc.codec === "vorbis" && enc.channels === 1 ? "pass" : "fail", value: `${enc.codec}/${enc.channels}ch/${enc.sampleRate}`, limit: "vorbis, mono", message: enc.channels === 1 ? "mono Ogg Vorbis (positional in game)" : "must be mono: stereo sounds ignore distance in Minecraft" });
  checks.push({ id: "true_peak", status: m.truePeakDb <= TRUE_PEAK_MAX ? "pass" : m.truePeakDb <= -0.3 ? "warn" : "fail", value: m.truePeakDb, limit: `<= ${TRUE_PEAK_MAX} dBTP`, message: m.truePeakDb <= TRUE_PEAK_MAX ? "no clipping headroom problem" : "too close to clipping" });
  const inBand = m.lufs >= prof.min && m.lufs <= prof.max;
  const near = m.lufs >= prof.min - 4 && m.lufs <= prof.max + 2;
  checks.push({ id: "loudness", status: inBand ? "pass" : near ? "warn" : "fail", value: m.lufs, limit: `${prof.min}..${prof.max} LUFS (${role})`, message: inBand ? `loudness fits a ${role} sound` : m.lufs < prof.min ? `quieter than a ${role} sound should be` : `louder than a ${role} sound should be` });
  checks.push({ id: "audible", status: m.samplePeakDb > -40 ? "pass" : "fail", value: m.samplePeakDb, limit: "> -40 dBFS peak", message: m.samplePeakDb > -40 ? "audible" : "practically silent" });
  checks.push({ id: "silence_ratio", status: m.silenceRatio <= 0.35 ? "pass" : m.silenceRatio <= 0.6 ? "warn" : "fail", value: m.silenceRatio, limit: "<= 0.35 (fail > 0.6)", message: m.silenceRatio <= 0.35 ? "little dead air" : "long silent stretches" });
  const dc = Math.abs(m.dcOffset);
  checks.push({ id: "dc_offset", status: dc <= 0.002 ? "pass" : dc <= 0.01 ? "warn" : "fail", value: m.dcOffset, limit: "|dc| <= 0.002 (fail > 0.01)", message: dc <= 0.002 ? "centred" : "the waveform is off-centre" });
  checks.push({ id: "duration", status: m.durationS >= 0.03 && m.durationS <= prof.maxSeconds ? "pass" : "fail", value: m.durationS, limit: `0.03..${prof.maxSeconds} s (${role})`, message: m.durationS > prof.maxSeconds ? `too long for a ${role} sound` : m.durationS < 0.03 ? "too short to hear" : "length fits" });
  const verdict = checks.some((c) => c.status === "fail") ? "fail" : checks.some((c) => c.status === "warn") ? "warn" : "pass";
  return { version: SOUND_QUALITY_VERSION, verdict, role, checks };
}
export const soundQualityProblems = (r: SoundQualityReport) => r.checks.filter((c) => c.status === "fail").map((c) => `${c.id}: ${c.message} (value ${c.value}, limit ${c.limit})`);

/** Highpass at 30 Hz used by the render chain before measuring (rumble the client speakers cannot play anyway). */
export const rumbleCut = (x: Mono) => biquad(x, "highpass", 30);

