// Cyrus asset catalog v2: CatalogEntry v1, ONE metadata record per library asset (3D model, PBR texture set,
// texture, sprite, HDRI, decal, sound, music), whatever its source (CC0 packs, the owner's proprietary library,
// Cyrus originals, community contributions from Cyrus users). The record is what Cyrus reads to PICK an asset for a
// situation, so it carries: what the asset is (title, <=140-char description, controlled tags, one primary + up to
// 3 secondary categories, situations it is good for), how good it is (quality score + the checks behind it), where
// it fits (per-game fit derived from each game's AssetProfile), technical facts, licence, provenance, the legal class
// of lib/cyrus/assets3d/manifest.ts and the moderation status.
// Pure, client-safe, Zod-validated; `catalogEntryJsonSchema()` is the portable contract. HOST SEAM: no Nxeon imports.
import { z } from "zod";
import { LEGAL_CLASSES } from "../../assets3d/manifest";
import type { AssetKind } from "../../engine-core/spec";
import type { LibraryKind } from "../types";

export const CATALOG_SCHEMA_VERSION = 1 as const;

export const CATALOG_KINDS = ["model", "texture-set", "texture", "sprite", "hdri", "decal", "sound", "music"] as const;
export type CatalogKind = (typeof CATALOG_KINDS)[number];

/** cc0 / cc-by: open licences; proprietary-nxeon: bought or owned by Nxeon (never redistributed as files); user-contributed: made in Cyrus by a customer (auto-contribution, owner decision 2026-10-10). */
export const LICENCE_TIERS = ["cc0", "cc-by", "proprietary-nxeon", "user-contributed"] as const;
export type LicenceTier = (typeof LICENCE_TIERS)[number];

/** pending-checks -> published | held; held -> published | removed; published -> held | removed. */
export const CATALOG_STATUSES = ["pending-checks", "published", "held", "removed"] as const;
export type CatalogStatus = (typeof CATALOG_STATUSES)[number];

export const FITS = ["good", "ok", "no"] as const;
export type Fit = (typeof FITS)[number];

/** Which enrichment stage last wrote the descriptive fields (title, description, tags, categories, useFor). */
export const ENRICHED_BY = ["stage-a", "stage-b", "owner", "contributor"] as const;
export type EnrichedBy = (typeof ENRICHED_BY)[number];

export const SHA256_HEX = /^[0-9a-f]{64}$/;
/** How a catalog asset is referenced everywhere outside the catalog (ModSpec asset slots, packs, logs). */
export const CATALOG_REF_RE = /^cat:[0-9a-f]{64}$/;
export const catalogRef = (id: string) => `cat:${id}`;
export const CATEGORY_ID_RE = /^[a-z0-9-]+\/[a-z0-9_-]+$/;
export const TAG_RE = /^[a-z0-9][a-z0-9-]{0,31}$/;
export const GAME_RE = /^[a-z][a-z0-9-]{1,31}$/;

const tag = z.string().regex(TAG_RE);
const cat = z.string().regex(CATEGORY_ID_RE);

export const QualityCheckZ = z.object({
  id: z.string().min(1).max(40),
  status: z.enum(["pass", "warn", "fail", "skip"]),
  weight: z.number().min(0).max(10),
  /** measured value or the reason it was skipped */
  detail: z.string().max(160),
}).strict();
export type QualityCheck = z.infer<typeof QualityCheckZ>;

export const QualityZ = z.object({
  /** 0-100; see lib/cyrus/library/catalog/quality.ts (version cq-1) */
  score: z.number().int().min(0).max(100),
  version: z.string().max(16),
  /** one line: how the score was computed (so an owner can audit it) */
  method: z.string().max(200),
  /** share of the check weight that was actually measured (0-1); unmeasured checks never count as passes */
  measured: z.number().min(0).max(1),
  checks: z.array(QualityCheckZ).max(30),
}).strict();
export type Quality = z.infer<typeof QualityZ>;

export const GameFitZ = z.object({
  fit: z.enum(FITS),
  reason: z.string().max(200),
  /** budget notes from the game's AssetProfile (poly budget, texture res, formats, delivery) */
  notes: z.array(z.string().max(160)).max(6).default([]),
  /** what Cyrus must do before shipping it to this game (convert, downscale, transcode...) */
  transform: z.array(z.string().max(40)).max(6).default([]),
}).strict();
export type GameFit = z.infer<typeof GameFitZ>;

const num = z.number().finite();
export const TechZ = z.object({
  format: z.string().max(32),
  bytes: z.number().int().min(0),
  // 3D
  triangles: z.number().int().min(0).nullable().optional(),
  vertices: z.number().int().min(0).nullable().optional(),
  meshes: z.number().int().min(0).nullable().optional(),
  materials: z.number().int().min(0).nullable().optional(),
  textures: z.number().int().min(0).nullable().optional(),
  /** axis-aligned size in glTF units (metres), [x, y, z] */
  bounds: z.tuple([num, num, num]).nullable().optional(),
  /** true when bounds look like real-world metres for the category (see vocab realWorldScale) */
  scaleOk: z.boolean().nullable().optional(),
  rigged: z.boolean().nullable().optional(),
  animations: z.number().int().min(0).nullable().optional(),
  // 2D / PBR / HDRI
  width: z.number().int().min(0).nullable().optional(),
  height: z.number().int().min(0).nullable().optional(),
  /** maps in a texture set (albedo, normal-gl, normal-dx, roughness, metallic, ao, height, opacity, emissive) */
  maps: z.array(z.string().max(16)).max(12).optional(),
  hasAlpha: z.boolean().nullable().optional(),
  tileable: z.boolean().nullable().optional(),
  /** physical size the texture covers (metres), when the source states it */
  physicalSizeM: z.number().positive().nullable().optional(),
  // audio
  durationS: z.number().min(0).nullable().optional(),
  sampleRate: z.number().int().min(0).nullable().optional(),
  channels: z.number().int().min(0).max(16).nullable().optional(),
  bitDepth: z.number().int().min(0).max(64).nullable().optional(),
  peakDb: num.nullable().optional(),
  truePeakDb: num.nullable().optional(),
  lufs: num.nullable().optional(),
  silenceRatio: z.number().min(0).max(1).nullable().optional(),
  /** HEURISTIC (start/end level match), never verified by ear */
  loopable: z.boolean().nullable().optional(),
  centroidHz: z.number().min(0).nullable().optional(),
  character: z.enum(["transient", "sustained"]).nullable().optional(),
}).strict();
export type Tech = z.infer<typeof TechZ>;

export const LicenceZ = z.object({
  tier: z.enum(LICENCE_TIERS),
  /** SPDX id when one applies (CC0-1.0, CC-BY-4.0); null for proprietary / user-contributed */
  spdx: z.string().max(40).nullable(),
  sourceUrl: z.string().max(300).nullable(),
  /** required text for cc-by; null otherwise */
  attribution: z.string().max(300).nullable(),
  /** what the ledger has actually seen: "verified: licence page saved 2026-10-10", "unverified: owner to confirm" */
  status: z.string().max(200),
}).strict();
export type Licence = z.infer<typeof LicenceZ>;

export const ProvenanceZ = z.object({
  source: z.string().max(40),
  pack: z.string().max(120).nullable(),
  /** path inside the staged/source library (never a customer path) */
  path: z.string().max(400).nullable(),
  retrievedAt: z.string().max(32).nullable(),
  /** upstream id / repo@sha the row came through */
  via: z.string().max(160).nullable(),
  /** content hashes this asset was derived from (a retexture lists its base) */
  derivedFrom: z.array(z.string().regex(SHA256_HEX)).max(16).default([]),
}).strict();

export const CatalogEntryV1Z = z.object({
  schemaVersion: z.literal(CATALOG_SCHEMA_VERSION),
  /** sha256 of the asset bytes (a texture set / HDRI: of its primary file); also the dedupe key */
  id: z.string().regex(SHA256_HEX),
  kind: z.enum(CATALOG_KINDS),
  title: z.string().trim().min(2).max(80),
  shortDescription: z.string().trim().min(10).max(140),
  /** controlled vocabulary (vocab.json tags / styles / object words) */
  tags: z.array(tag).max(16),
  /** anything else that looked useful, max 8 */
  freeTags: z.array(tag).max(8).default([]),
  categories: z.object({ primary: cat, secondary: z.array(cat).max(3).default([]) }).strict(),
  /** situation ids from vocab.json useFor */
  useFor: z.array(z.string().regex(/^[a-z0-9-]{2,48}$/)).max(8).default([]),
  style: z.string().max(24).nullable(),
  quality: QualityZ,
  /** game id -> fit, only for games with an AssetProfile; missing game = unknown (never assumed good) */
  games: z.record(z.string().regex(GAME_RE), GameFitZ).default({}),
  tech: TechZ,
  licence: LicenceZ,
  provenance: ProvenanceZ,
  legalClass: z.enum(LEGAL_CLASSES),
  /** opaque contributor id (never an email or a Nxeon user id); null for packs */
  contributedBy: z.string().regex(/^[a-z0-9_-]{4,64}$/).nullable().default(null),
  status: z.enum(CATALOG_STATUSES),
  /** why the status is what it is (content-filter flags, owner note) */
  statusReason: z.string().max(300).nullable().default(null),
  /** content-filter flag ids (lib/cyrus/library/catalog/filters.ts) */
  flags: z.array(z.string().max(48)).max(12).default([]),
  /** near-duplicate / variant group: same stem + sizes in other colours or numbering */
  group: z.string().max(120).nullable().default(null),
  /** sha256 of a better copy when this one is a near-duplicate */
  duplicateOf: z.string().regex(SHA256_HEX).nullable().default(null),
  thumbnail: z.string().max(400).nullable().default(null),
  enrichment: z.object({
    by: z.enum(ENRICHED_BY),
    /** 0-1: how sure the stage was that title/category/useFor are right */
    confidence: z.number().min(0).max(1),
    /** full = stage A described it well enough to pick; partial = category only; none = needs stage B */
    coverage: z.enum(["full", "partial", "none"]),
    /** stage-b model id, when stage B ran */
    model: z.string().max(60).nullable().default(null),
    at: z.string().max(32),
    /** what stage A could not decide (feeds the stage-B queue and the owner review) */
    gaps: z.array(z.string().max(80)).max(8).default([]),
  }).strict(),
}).strict();

export type CatalogEntry = z.output<typeof CatalogEntryV1Z>;
export type CatalogEntryInput = z.input<typeof CatalogEntryV1Z>;
export type EntryIssue = { path: string; code: string; message: string };

/** Structured validation (never throws) + cross-field rules. */
export function validateCatalogEntry(raw: unknown): { ok: true; entry: CatalogEntry } | { ok: false; errors: EntryIssue[] } {
  const r = CatalogEntryV1Z.safeParse(raw);
  if (!r.success) return { ok: false, errors: r.error.issues.map((i) => ({ path: i.path.join(".") || "entry", code: "invalid", message: i.message })) };
  const e = r.data;
  const errors: EntryIssue[] = [];
  const add = (path: string, code: string, message: string) => errors.push({ path, code, message });
  if (e.categories.secondary.includes(e.categories.primary)) add("categories.secondary", "duplicate_primary", "a secondary category repeats the primary");
  if (e.licence.tier === "cc-by" && !e.licence.attribution) add("licence.attribution", "attribution_required", "cc-by assets need their attribution text");
  if (e.licence.tier === "user-contributed" && !e.contributedBy) add("contributedBy", "contributor_required", "a user-contributed asset names its (opaque) contributor");
  if (e.licence.tier !== "user-contributed" && e.contributedBy) add("contributedBy", "contributor_only_for_user", "only user-contributed assets carry a contributor");
  if (e.legalClass === "game-derived" || e.legalClass === "third-party-licensed") add("legalClass", "not_library_class", `${e.legalClass} content never enters the catalog`);
  if (e.licence.tier === "user-contributed" && !["user-original", "ai-generated-for-user"].includes(e.legalClass)) add("legalClass", "contribution_class", "community contributions are user-original or ai-generated-for-user");
  if ((e.licence.tier === "cc0" || e.licence.tier === "cc-by" || e.licence.tier === "proprietary-nxeon") && e.legalClass !== "platform-library") add("legalClass", "library_class", "pack and Nxeon library assets are platform-library");
  if (e.status === "published" && e.flags.some((f) => f.startsWith("hold:"))) add("status", "published_with_hold", "an entry with a hold flag cannot be published");
  if (e.duplicateOf === e.id) add("duplicateOf", "self_duplicate", "an entry cannot duplicate itself");
  const audio = e.kind === "sound" || e.kind === "music";
  if (audio && e.tech.triangles != null) add("tech.triangles", "kind_mismatch", "audio has no triangles");
  return errors.length ? { ok: false, errors } : { ok: true, entry: e };
}

/** JSON Schema (draft 2020-12) of CatalogEntry v1: the portable contract for the host's store and other tools. */
export function catalogEntryJsonSchema(): Record<string, unknown> {
  const s = z.toJSONSchema(CatalogEntryV1Z, { target: "draft-2020-12", io: "input" }) as Record<string, unknown>;
  return { $id: "https://nxeon.cloud/schemas/cyrus/catalog-entry.v1.json", title: "Cyrus CatalogEntry v1", ...s };
}

/** The plan-gate kind (lib/cyrus/engine-core/asset-gate.ts) of a catalog kind: sounds follow the Sound Studio, everything visual the Texture Studio. */
export function gateKindOf(kind: CatalogKind): AssetKind {
  if (kind === "sound" || kind === "music") return "sound";
  if (kind === "model") return "model";
  return "texture";
}
/** The unified-library kind (lib/cyrus/library/types.ts) of a catalog kind. */
export const libraryKindOf = (kind: CatalogKind): LibraryKind => (kind === "sound" || kind === "music" ? "sound" : kind === "model" ? "model" : "texture");

