// Typed access to the catalog vocabulary (vocab.json = data) plus the deterministic word handling every stage
// shares: path/filename tokenising (camelCase, snake_case, Soundminer comma tags, doubled extensions), synonym
// folding through BOTH existing taxonomies (sound + texture) and vocab.json, and the "is this a real content word"
// test that decides stage-A coverage. Pure, client-safe.
import vocabJson from "./vocab.json";
import { TAXONOMY as SOUND_TAX } from "../../sound/classify";
import { TEXTURE_TAXONOMY as TEX_TAX } from "../../texture-library/compile";
import type { CatalogKind } from "./entry";

export type UseForRule = {
  id: string; label: string; kinds: CatalogKind[];
  categoriesAny?: string[]; tagsAny?: string[]; tagsAll?: string[]; useCasesAny?: string[]; stylesAny?: string[];
};
type Vocab = {
  version: number;
  styles: string[];
  styleKeywords: Record<string, string[]>;
  categories: { id: string; keywords: string[] }[];
  categoryAliases: Record<string, string>;
  tags: Record<string, string[]>;
  synonyms: Record<string, string>;
  genericWords: string[];
  useFor: UseForRule[];
  realWorldScale: Record<string, number | string>;
  sourceStyles: Record<string, string[] | string>;
  packStyleHints: Record<string, string>;
};
export const VOCAB = vocabJson as unknown as Vocab;
export const CATEGORY_IDS: readonly string[] = VOCAB.categories.map((c) => c.id);
export const USE_FOR_IDS: readonly string[] = VOCAB.useFor.map((u) => u.id);
export const isCategory = (id: string) => CATEGORY_IDS.includes(id);
export const useForLabel = (id: string) => VOCAB.useFor.find((u) => u.id === id)?.label ?? id;

const GENERIC = new Set(VOCAB.genericWords);
/** canonical form of one word: vocab synonyms, then the sound and texture taxonomies' synonym tables */
export function canon(w: string): string {
  return VOCAB.synonyms[w] ?? SOUND_TAX.synonyms[w] ?? TEX_TAX.synonyms[w] ?? w;
}

/** every controlled tag (tag facets + styles + category keywords + both taxonomies' keywords), canonical */
export const CONTROLLED = (() => {
  const s = new Set<string>();
  for (const list of Object.values(VOCAB.tags)) for (const t of list) s.add(t);
  for (const st of VOCAB.styles) s.add(st);
  for (const c of VOCAB.categories) for (const k of c.keywords) s.add(canon(k));
  for (const c of SOUND_TAX.categories) for (const k of c.keywords) s.add(canon(k));
  for (const u of SOUND_TAX.useCases) for (const k of u.keywords) s.add(canon(k));
  for (const c of TEX_TAX.categories) for (const sub of c.subcategories ?? []) for (const k of sub.keywords ?? []) s.add(canon(k));
  for (const u of VOCAB.useFor) for (const t of [...(u.tagsAny ?? []), ...(u.tagsAll ?? [])]) s.add(t);
  return s;
})();
export const isControlled = (t: string) => CONTROLLED.has(t);

/** split camelCase / PascalCase / letter-digit boundaries: "playerBlue_duck" -> "player Blue duck", "Metal033" -> "Metal 033" */
const splitCase = (s: string) => s.replace(/([a-z])([A-Z])/g, "$1 $2").replace(/([A-Z]+)([A-Z][a-z])/g, "$1 $2").replace(/([A-Za-z])(\d)/g, "$1 $2").replace(/(\d)([A-Za-z])/g, "$1 $2");
export const stripExt = (name: string) => name.replace(/(\.(mp3|wav|aif|aiff|ogg|flac|png|jpg|jpeg|glb|gltf|hdr|exr|webp|mtlx|usdc|blend))+$/i, "");

/** raw lowercase words of a string (no synonym folding), digits kept as their own tokens */
export function words(s: string): string[] {
  return splitCase(s).toLowerCase().replace(/['’]/g, "").replace(/×/g, " x ").split(/[^a-z0-9]+/).filter(Boolean);
}
export const canonWords = (s: string) => words(s).map(canon);
const isNumberish = (w: string) => /^\d+$/.test(w) || /^\d+(x|k|px|mm|m|s|hz|khz|bit)$/.test(w) || /^v\d+$/.test(w);
/** a word that can describe content: alphabetic, >= 3 letters (or a known 2-letter word), not a generic file word */
export const isContentWord = (w: string) => !isNumberish(w) && !GENERIC.has(w) && /[a-z]/.test(w) && (w.length >= 3 || CONTROLLED.has(w));

export type PathTokens = {
  /** words of the file name (without extension), canonical */
  file: string[];
  /** words of the folders between the pack root and the file, canonical, generic words removed */
  folders: string[];
  /** Soundminer-style comma metadata in the file name ("Vaeyan,shockabsorber,broken,...") */
  commaTags: string[];
  /** trailing take / variant number, when the name ends in one */
  number: string | null;
};

/** Tokenise a library path. `packDepth` = how many leading segments are source/pack (they are not content). */
export function pathTokens(path: string, packDepth = 2): PathTokens {
  const segs = path.split("/").filter(Boolean);
  const fileName = stripExt(segs[segs.length - 1] ?? "");
  const folderSegs = segs.slice(packDepth, -1).filter((s) => !/^(png|jpg|default|default size|vector|svg|tiles|sprites|preview|models|textures|sounds|audio|files|\d+)$/i.test(s.trim()));
  let commaTags: string[] = [];
  let main = fileName;
  if ((fileName.match(/,/g) ?? []).length >= 2) {
    const parts = fileName.split(",").map((p) => p.trim()).filter(Boolean);
    main = parts[0];
    commaTags = [...new Set(parts.slice(1).flatMap((p) => words(p)).map(canon).filter(isContentWord))];
  }
  const num = main.match(/(?:^|[\s_\-.])0*(\d{1,5})\s*[a-z]?$/i);
  return {
    file: words(main).map(canon),
    folders: [...new Set(folderSegs.flatMap((s) => words(s)).map(canon).filter(isContentWord))],
    commaTags,
    number: num ? num[1] : null,
  };
}

/** "arrow_bundle" -> "Arrow bundle"; keeps a trailing variant number; drops generic noise words except as the only word */
export function humanTitle(ws: string[], fallback: string): string {
  const kept = ws.filter((w) => !GENERIC.has(w) || isNumberish(w));
  const out = (kept.length ? kept : ws).join(" ").replace(/\s+/g, " ").trim();
  const t = out || fallback;
  return (t.charAt(0).toUpperCase() + t.slice(1)).slice(0, 80);
}

/** Cut to <= max chars on a word boundary, ending with a full stop. */
export function clip(s: string, max: number): string {
  const one = s.replace(/\s+/g, " ").trim();
  if (one.length <= max) return one;
  const cut = one.slice(0, max - 1);
  const at = cut.lastIndexOf(" ");
  return `${(at > max * 0.6 ? cut.slice(0, at) : cut).replace(/[,;:\-\s]+$/, "")}.`;
}

export const slugTag = (w: string) => w.toLowerCase().replace(/[^a-z0-9-]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 32);

