  durationS: number; sampleRate: number; channels: number; bitDepth: number | null; peakDb: number; truePeakDb: number; lufs: number;
  silenceRatio: number; dcOffset: number; loopable: boolean; centroidHz: number; character: "transient" | "sustained";
  durationClass: string; intensity: string; pitchBand: string;
};

/** Measured audio features (the same code the sound library manifest uses), from a decoded mono buffer. */
export function audioFacts(mono: Mono, sampleRate: number, channels: number, bitDepth: number | null): AudioTech {
  const m = measure(mono, sampleRate);
  const raw = rawDescriptors(mono, sampleRate);
  const d = describe({ duration: m.durationS, channels, lufs: m.lufs <= -998 ? null : m.lufs, samplePeakDb: m.samplePeakDb, raw });
  return {
    durationS: m.durationS, sampleRate, channels, bitDepth, peakDb: m.samplePeakDb, truePeakDb: m.truePeakDb, lufs: m.lufs, silenceRatio: m.silenceRatio,
    dcOffset: m.dcOffset, loopable: d.loopable, centroidHz: raw.centroidHz, character: d.character, durationClass: d.durationClass, intensity: d.intensity, pitchBand: d.pitchBand,
  };
}

export function pngFacts(bytes: Uint8Array): { ok: true; width: number; height: number; hasAlpha: boolean | null } | Fail {
  const sig = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a];
  if (bytes.length < 33 || sig.some((b, i) => bytes[i] !== b)) return { ok: false, error: "not a PNG" };
