  const colourType = bytes[25];
  // colour types 4/6 carry alpha; palette (3) may via tRNS, which we do not scan here -> null (unknown)
  return { ok: true, width: dv.getUint32(16), height: dv.getUint32(20), hasAlpha: colourType === 4 || colourType === 6 ? true : colourType === 3 ? null : false };
}

