// Catalog quality score `cq-1` (0-100), deterministic, zero tokens. It says how SAFE and USABLE an asset is to
// pick automatically, not how pretty it is (a vision/ear judge calibrated on owner labels is a later stage C item).
//   score = round( 100 * sum(weight * s) / sum(weight of MEASURED checks) * (0.7 + 0.3 * measuredShare) )
//   s: pass 1, warn 0.5, fail 0; skip = not measured (left out of the ratio, but lowers measuredShare)
//   any check marked `hard` that fails caps the score at 20 (corrupt file, silent audio, zero triangles).
// So an asset whose facts were never measured cannot score above 70, and every number is explainable per check.
import type { CatalogKind, Quality, QualityCheck, Tech } from "./entry";

export const QUALITY_VERSION = "cq-1";
type Status = QualityCheck["status"];
type C = QualityCheck & { hard?: boolean };

export type QualityInput = {
  kind: CatalogKind;
  tech: Tech;
  licenceDocumented: boolean;
  hasThumbnail: boolean;
  /** stage-A confidence that title/category are right */
  metadataConfidence: number;
  /** the decoder/parser failed on the bytes */
  corrupt?: string | null;
  /** category's typical real-world height (m), when known */
  expectedHeightM?: number | null;
};

const c = (id: string, status: Status, weight: number, detail: string, hard = false): C => ({ id, status, weight, detail: detail.slice(0, 160), ...(hard ? { hard } : {}) });
const skip = (id: string, weight: number, why = "not measured") => c(id, "skip", weight, why);
const pow2 = (n: number) => n > 0 && (n & (n - 1)) === 0;

function modelChecks(t: Tech, q: QualityInput): C[] {
  const out: C[] = [];
  out.push(c("format", t.format === "glb" ? "pass" : t.format === "gltf" ? "warn" : "fail", 1, `format ${t.format}`));
  if (t.triangles == null) out.push(skip("triangles", 3));
  else out.push(c("triangles", t.triangles === 0 ? "fail" : t.triangles <= 50_000 ? "pass" : t.triangles <= 300_000 ? "warn" : "fail", 3, `${t.triangles} tris (warn > 50k, fail > 300k)`, t.triangles === 0));
  out.push(t.bytes ? c("file_size", t.bytes <= 20e6 ? "pass" : t.bytes <= 100e6 ? "warn" : "fail", 1, `${Math.round(t.bytes / 1024)} KiB`) : skip("file_size", 1));
  if (t.materials == null) out.push(skip("materials", 1));
  else out.push(c("materials", t.materials >= 1 && t.materials <= 16 ? "pass" : t.materials === 0 ? "warn" : "warn", 1, `${t.materials} materials`));
  if (!t.bounds) out.push(skip("scale", 1));
  else {
    const h = Math.max(...t.bounds);
    const exp = q.expectedHeightM;
    const ok = h > 0.005 && h < 500 && (!exp || (h / exp < 10 && exp / h < 10));
    out.push(c("scale", ok ? "pass" : "warn", 1, `largest side ${h} m${exp ? ` (typical ${exp} m)` : ""}`));
  }
  return out;
}

function textureSetChecks(t: Tech): C[] {
  const maps = new Set(t.maps ?? []);
  const core = ["albedo", "roughness"].every((m) => maps.has(m)) && (maps.has("normal-gl") || maps.has("normal-dx"));
  const out: C[] = [];
  out.push(t.maps ? c("pbr_maps", core ? "pass" : maps.has("albedo") ? "warn" : "fail", 3, `maps: ${[...maps].join(", ") || "none"}`) : skip("pbr_maps", 3));
  out.push(t.maps ? c("normal_convention", maps.has("normal-gl") && maps.has("normal-dx") ? "pass" : maps.has("normal-gl") || maps.has("normal-dx") ? "warn" : "skip", 1, maps.has("normal-gl") && maps.has("normal-dx") ? "OpenGL + DirectX normals" : "one convention (adapter converts)") : skip("normal_convention", 1));
  out.push(t.width ? c("resolution", t.width >= 1024 ? "pass" : t.width >= 512 ? "warn" : "fail", 1, `${t.width}px`) : skip("resolution", 1));
  out.push(t.physicalSizeM != null ? c("physical_size", "pass", 1, `${t.physicalSizeM} m`) : skip("physical_size", 1, "physical size not stated"));
  return out;
}

function imageChecks(t: Tech, kind: CatalogKind): C[] {
  const out: C[] = [];
  if (!t.width || !t.height) return [skip("dimensions", 2), skip("power_of_two", 1)];
  const big = Math.max(t.width, t.height);
  out.push(c("dimensions", big < 4 ? "fail" : big <= 4096 ? "pass" : "warn", 2, `${t.width}x${t.height}`, big < 4));
  out.push(c("power_of_two", pow2(t.width) && pow2(t.height) ? "pass" : "warn", 1, pow2(t.width) && pow2(t.height) ? "power-of-two" : "not power-of-two (padding needed for mip-mapped engines)"));
  if (kind === "hdri") out.push(c("hdri_resolution", t.width >= 2048 ? "pass" : "warn", 2, `${t.width}px wide`));
  if (kind === "sprite" || kind === "decal") out.push(t.hasAlpha == null ? skip("alpha", 1) : c("alpha", t.hasAlpha ? "pass" : "warn", 1, t.hasAlpha ? "has alpha" : "no alpha channel"));
  return out;
}

function audioChecks(t: Tech, kind: CatalogKind, corrupt: string | null | undefined): C[] {
  if (corrupt) return [c("decode", "fail", 2, corrupt, true)];
  if (t.durationS == null) return [skip("decode", 2), skip("duration", 1), skip("true_peak", 2), skip("silence", 1), skip("sample_rate", 1), skip("loudness", 1)];
  const out: C[] = [c("decode", "pass", 2, "decoded")];
  const maxS = kind === "music" ? 900 : 600;
  out.push(c("duration", t.durationS < 0.03 ? "fail" : t.durationS <= maxS ? "pass" : "warn", 1, `${t.durationS} s`, t.durationS < 0.03));
  if (t.peakDb != null && t.peakDb < -40) out.push(c("audible", "fail", 2, `peak ${t.peakDb} dBFS (practically silent)`, true));
  if (t.truePeakDb == null) out.push(skip("true_peak", 2));
  else out.push(c("true_peak", t.truePeakDb <= -0.3 ? "pass" : t.truePeakDb <= 0.5 ? "warn" : "fail", 2, `${t.truePeakDb} dBTP (clipping risk above -0.3)`));
  if (t.silenceRatio == null) out.push(skip("silence", 1));
  else out.push(c("silence", t.silenceRatio <= 0.35 ? "pass" : t.silenceRatio <= 0.6 ? "warn" : "fail", 1, `silence ratio ${t.silenceRatio}`));
  if (t.sampleRate == null) out.push(skip("sample_rate", 1));
  else out.push(c("sample_rate", t.sampleRate >= 44100 ? "pass" : t.sampleRate >= 22050 ? "warn" : "fail", 1, `${t.sampleRate} Hz`));
  if (t.lufs == null) out.push(skip("loudness", 1));
  else out.push(c("loudness", t.lufs >= -35 && t.lufs <= -6 ? "pass" : "warn", 1, `${t.lufs} LUFS (normalised per role at build time)`));
  return out;
}

export function catalogQuality(q: QualityInput): Quality {
  const t = q.tech;
  const checks: C[] = [];
  if (q.corrupt && q.kind !== "sound" && q.kind !== "music") checks.push(c("parse", "fail", 2, q.corrupt, true));
  else if (q.kind === "model") checks.push(...modelChecks(t, q));
  else if (q.kind === "texture-set") checks.push(...textureSetChecks(t));
  else if (q.kind === "sound" || q.kind === "music") checks.push(...audioChecks(t, q.kind, q.corrupt));
  else checks.push(...imageChecks(t, q.kind));
  checks.push(c("licence", q.licenceDocumented ? "pass" : "fail", 2, q.licenceDocumented ? "licence source recorded" : "no licence source"));
  checks.push(c("thumbnail", q.hasThumbnail ? "pass" : "warn", 1, q.hasThumbnail ? "preview exists" : "no preview image"));
  checks.push(c("metadata", q.metadataConfidence >= 0.75 ? "pass" : q.metadataConfidence >= 0.45 ? "warn" : "fail", 1, `stage-A confidence ${q.metadataConfidence.toFixed(2)}`));
  const val: Record<Status, number> = { pass: 1, warn: 0.5, fail: 0, skip: 0 };
  const total = checks.reduce((s, x) => s + x.weight, 0);
  const measuredW = checks.filter((x) => x.status !== "skip").reduce((s, x) => s + x.weight, 0);
  const got = checks.filter((x) => x.status !== "skip").reduce((s, x) => s + x.weight * val[x.status], 0);
  const share = total ? measuredW / total : 0;
  let score = measuredW ? Math.round((100 * got / measuredW) * (0.7 + 0.3 * share)) : 0;
  if (checks.some((x) => x.hard && x.status === "fail")) score = Math.min(score, 20);
  return {
    score: Math.max(0, Math.min(100, score)), version: QUALITY_VERSION,
    method: "weighted pass ratio of measured checks x (0.7 + 0.3 x measured share); hard fail caps at 20",
    measured: Math.round(share * 100) / 100,
    checks: checks.map(({ hard: _h, ...rest }) => rest),
  };
}

