// Per-game suitability: does a catalog asset fit game X, and what would Cyrus have to do to it? Derived ONLY from
// the game's AssetProfile (lib/cyrus/adapters/asset-profile.ts, incl. its optional `catalog` hints) and the asset's
// own facts. Rules (honest by construction):
//   good = usable now as is, or through a converter Cyrus HAS (sound -> mono Ogg), and in a style the game likes
//   ok   = usable now but off-style, or over budget in a way Cyrus can live with (noted)
//   no   = needs something Cyrus does not have (a mesh converter, a downscaler) or the game cannot use the kind
// A game without catalog hints gets NO row: missing = unknown, and ranking treats unknown below ok.
import type { AssetProfile } from "../../adapters/asset-profile";
import type { CatalogKind, GameFit, Tech } from "./entry";

export type FitSubject = { kind: CatalogKind; style: string | null; tags: readonly string[]; categories: { primary: string; secondary: readonly string[] }; tech: Tech };

/** Transforms that EXIST in Cyrus today (a fit may only rely on these). */
export const AVAILABLE_TRANSFORMS = ["ogg-mono", "loudness-normalise"] as const;

const isAudio = (k: CatalogKind) => k === "sound" || k === "music";
const charLike = (s: FitSubject) => s.categories.primary.startsWith("characters/") || s.categories.primary.startsWith("creatures/");
const vehicleLike = (s: FitSubject) => s.categories.primary.startsWith("vehicles/");

export function gameFit(s: FitSubject, profile: AssetProfile): GameFit | null {
  const h = profile.catalog;
  if (!h) return null;
  const mode = h.accepts[s.kind] ?? "none";
  const notes: string[] = [`delivery: ${profile.delivery}`];
  if (mode === "none") return { fit: "no", reason: (h.noneReasons?.[s.kind] ?? `${profile.game} cannot use ${s.kind} assets`).slice(0, 200), notes: [], transform: [] };
  const styleOk = !h.styleAffinity.length || (s.style != null && h.styleAffinity.includes(s.style)) || s.tags.some((t) => h.styleAffinity.includes(t));

  if (isAudio(s.kind)) {
    const a = h.audio;
    const transform: string[] = [];
    if (a) {
      notes.push(`target ${a.format}, ${a.channels === 1 ? "mono" : `${a.channels} ch`}`);
      if (a.note) notes.push(a.note);
      if (s.tech.channels == null || s.tech.channels !== a.channels || s.tech.format !== a.format) transform.push("ogg-mono");
    }
    transform.push("loudness-normalise");
    if (a?.maxSeconds && s.tech.durationS != null && s.tech.durationS > a.maxSeconds) return { fit: "ok", reason: `longer than ${a.maxSeconds} s; trim before use`, notes, transform };
    if (s.tech.durationS == null) return { fit: "ok", reason: "audio not measured yet", notes, transform };
    return { fit: "good", reason: transform.includes("ogg-mono") ? "plays after the standard mono Ogg transcode" : "plays as is", notes, transform };
  }

  if (s.kind === "model") {
    const b = h.triBudget;
    const tris = s.tech.triangles;
    if (!b) return { fit: mode === "native" ? "ok" : "no", reason: "no triangle budget declared for this game", notes, transform: [] };
    const budget = charLike(s) ? b.character : vehicleLike(s) ? b.vehicle : b.prop;
    notes.push(`tri budget ${budget} (${charLike(s) ? "character" : vehicleLike(s) ? "vehicle" : "prop"})`);
    if (charLike(s) && s.tech.rigged === false && s.tags.includes("animated")) notes.push("animated but no skin");
    if (tris == null) return { fit: "ok", reason: "triangle count not measured", notes, transform: mode === "convert" ? ["mesh-convert"] : [] };
    if (tris > budget * 4) return { fit: "no", reason: `${tris} tris is over 4x the ${budget} budget (no LOD tool yet)`, notes, transform: [] };
    const over = tris > budget;
    return { fit: over || !styleOk ? "ok" : "good", reason: over ? `${tris} tris, over the ${budget} budget` : styleOk ? `${tris} tris, within budget` : `within budget but ${s.style ?? "unstyled"} is off-style`, notes, transform: mode === "convert" ? ["mesh-convert"] : [] };
  }

  // 2D: textures, sprites, texture sets, HDRIs, decals
  const r = h.textureRes;
  const w = s.tech.width ?? null, ht = s.tech.height ?? null;
  if (r) notes.push(`texture sizes ${r.ideal.join("/")} px (max ${r.max})`);
  if (w == null || ht == null) return { fit: "ok", reason: "size not measured", notes, transform: [] };
  if (r) {
    const square = w === ht;
    if (w > r.max || ht > r.max) return { fit: "no", reason: `${w}x${ht} needs a downscale to ${r.max} px or less (no downscaler yet)`, notes, transform: [] };
    if (!r.ideal.includes(w) || !square) {
      if (square && w <= r.max) return { fit: styleOk ? "ok" : "ok", reason: `${w}x${ht} is allowed for skins/atlases, not item slots`, notes, transform: [] };
      return { fit: "no", reason: `${w}x${ht} is not one of ${r.ideal.join("/")} px square (no pad/resize step yet)`, notes, transform: [] };
    }
  }
  return { fit: styleOk ? "good" : "ok", reason: styleOk ? `${w}x${ht}, in the game's style` : `${w}x${ht} fits, but ${s.style ?? "the style"} is off-style for ${profile.game}`, notes, transform: [] };
}

/** Fit rows for every profile that declares catalog hints. */
export function gameFits(s: FitSubject, profiles: readonly AssetProfile[]): Record<string, GameFit> {
  const out: Record<string, GameFit> = {};
  for (const p of profiles) { const f = gameFit(s, p); if (f) out[p.game] = f; }
  return out;
}

