// Enrichment STAGE A: deterministic, zero model tokens. Turns one raw library row (the ingest catalog.jsonl shape,
// a sound-library file, a community contribution) plus whatever is known for free (pack metadata JSON, upstream
// tags, measured facts from ./extract.ts) into a full CatalogEntry, and says honestly how well it did:
//   coverage full    = a real title, a confident primary category and >= 1 situation (useFor): Cyrus can pick it
//   coverage partial = category + tags, but a weak title or no situation (findable by browsing, weak for picking)
//   coverage none    = opaque name and no usable category: queued for stage B (vision / audio features)
// Signals, strongest first: measured facts > pack metadata item (name/category/styles/themes) > upstream tags >
// the source's own category string (vocab categoryAliases) > filename words > folder words > pack-name words.
// Sound rows reuse lib/cyrus/sound/classify.ts (the taxonomy the 514-file library already uses).
import type { AssetProfile } from "../../adapters/asset-profile";
import type { LegalClass } from "../../assets3d/manifest";
import { classify, TAXONOMY as SOUND_TAX } from "../../sound/classify";
import { CATALOG_SCHEMA_VERSION, validateCatalogEntry, type CatalogEntry, type CatalogKind, type LicenceTier, type Tech, type EntryIssue } from "./entry";
import type { AudioTech, GlbFacts } from "./extract";
import { gameFits } from "./fit";
import { catalogQuality } from "./quality";
import { canon, clip, humanTitle, isContentWord, isControlled, pathTokens, slugTag, useForLabel, VOCAB, words, type PathTokens } from "./vocab";

/** One row of the ingest agent's catalog.jsonl (fields it may or may not fill). */
export type RawAsset = {
  id: string; source: string; pack: string; path: string; kind: string; format: string; sizeBytes: number;
  category?: string | null; triangles?: number | null; width?: number | null; height?: number | null;
  licenseSpdx?: string | null; licenseUrl?: string | null; sourceUrl?: string | null; retrievedAt?: string | null; attribution?: string | null;
  tier: string; via?: string | null; tags?: string[] | null; name?: string | null; resolution?: string | null; upstreamId?: string | null;
  thumbnail?: string | null;
};
/** Free metadata from the pack (Papyszoo items.json, Poly Haven / ambientCG API rows, the sound manifest). */
export type SideMeta = {
  name?: string | null; description?: string | null; category?: string | null; subcategory?: string | null;
  tags?: string[] | null; styles?: string[] | null; themes?: string[] | null;
  /** files of a texture set / HDRI folder (map names are read from them) */
  files?: string[] | null;
  physicalSizeM?: number | null; thumbnail?: string | null;
  /** owner-provided sound-library classification (lib/cyrus/sound/library.manifest.json) */
  soundCategory?: string | null; soundUseCases?: string[] | null;
};
export type Measured = { glb?: GlbFacts | null; audio?: AudioTech | null; image?: { width: number; height: number; hasAlpha: boolean | null } | null; corrupt?: string | null };
export type PackInfo = { title: string; creator?: string | null };
export type StageAContext = {
  profiles: readonly AssetProfile[];
  packs?: Readonly<Record<string, PackInfo>>;
  /** ISO timestamp written into enrichment.at (inject for reproducible golden tests) */
  now: string;
  legalClass?: LegalClass;
  contributedBy?: string | null;
  licenceStatus?: string;
};
export type StageAResult = { entry: CatalogEntry | null; errors: EntryIssue[]; coverage: "full" | "partial" | "none"; gaps: string[]; needsStageB: boolean };

const KIND_ALIASES: Record<string, CatalogKind> = { model: "model", "texture-set": "texture-set", texture: "texture", sprite: "sprite", hdri: "hdri", decal: "decal", sound: "sound", music: "music", audio: "sound" };
const TIER_ALIASES: Record<string, LicenceTier> = { cc0: "cc0", "cc-by": "cc-by", ccby: "cc-by", proprietary: "proprietary-nxeon", "proprietary-nxeon": "proprietary-nxeon", owner: "proprietary-nxeon", user: "user-contributed", "user-contributed": "user-contributed" };
const DOMAINS: Record<CatalogKind, string[]> = {
  model: ["weapons", "architecture", "nature", "props", "furniture", "decor", "characters", "creatures", "vehicles", "food", "household", "toys", "music", "scifi", "items"],
  sprite: ["weapons", "nature", "props", "characters", "creatures", "vehicles", "food", "household", "ui", "vfx", "tiles", "items", "sprites", "architecture", "furniture"],
  decal: ["material", "props", "decor"],
  texture: ["material", "tiles", "vfx", "ui"],
  "texture-set": ["material"],
  hdri: ["env"],
  sound: ["sound"],
  music: ["music"],
};
const MAP_PATTERNS: [RegExp, string][] = [[/_(color|basecolor|albedo|diff(use)?)\b/i, "albedo"], [/_normalgl\b|_nor_gl\b/i, "normal-gl"], [/_normaldx\b|_nor_dx\b/i, "normal-dx"], [/_rough(ness)?\b/i, "roughness"], [/_metal(ness|lic)?\b/i, "metallic"], [/_(ambientocclusion|ao)\b/i, "ao"], [/_(displacement|height|disp)\b/i, "height"], [/_opacity\b|_alpha\b/i, "opacity"], [/_emissi(on|ve)\b/i, "emissive"]];

const lowerKey = (s: string) => s.toLowerCase().replace(/\s+tile size.*$/i, "").replace(/\s+/g, " ").trim();
const resolutionPx = (r: string | null | undefined) => { const m = r?.match(/(\d+)\s*k/i); return m ? Number(m[1]) * 1024 : null; };

type Vote = Map<string, number>;
const vote = (v: Vote, id: string, w: number) => v.set(id, (v.get(id) ?? 0) + w);

/** keyword votes for categories in the kind's domains */
function keywordVotes(v: Vote, ws: readonly string[], w: number, kind: CatalogKind) {
  const doms = DOMAINS[kind];
  for (const c of VOCAB.categories) {
    if (!doms.includes(c.id.split("/")[0])) continue;
    const kw = c.keywords.map(canon);
    const hits = ws.filter((x) => kw.includes(x)).length;
    if (hits) vote(v, c.id, w * Math.min(hits, 2));
  }
}

function aliasOf(raw: string | null | undefined): string | null {
  if (!raw) return null;
  const k = lowerKey(raw);
  return VOCAB.categoryAliases[k] ?? null;
}

function detectStyle(all: readonly string[], raw: RawAsset, side: SideMeta | undefined, kind: CatalogKind): string | null {
  const bag = new Set(all);
  for (const s of side?.styles ?? []) for (const w of words(s)) bag.add(w);
  const st = (side?.styles ?? []).map((s) => s.toLowerCase().replace(/\s+/g, "-"));
  for (const s of st) { const c = canon(s); if (VOCAB.styles.includes(c)) return c; }
  for (const [style, kws] of Object.entries(VOCAB.styleKeywords)) if (kws.some((k) => bag.has(k) || bag.has(canon(k)))) return style;
  for (const w of words(raw.pack)) { const h = VOCAB.packStyleHints[w]; if (h && !w.startsWith("_")) return h; }
  const is3d = kind === "model";
  const key = raw.source === "kenney" ? (is3d ? "kenney-3d" : "kenney-2d") : raw.source;
  const house = VOCAB.sourceStyles[key];
  return Array.isArray(house) ? house[0] : null;
}

function soundSide(raw: RawAsset, pt: PathTokens, side: SideMeta | undefined, audio: AudioTech | null | undefined) {
  const file = raw.path.split("/").pop() ?? raw.path;
  const facts = { duration: audio?.durationS ?? 1, channels: audio?.channels ?? 2, lufs: audio?.lufs ?? null, samplePeakDb: audio?.peakDb ?? null, raw: { centroidHz: audio?.centroidHz ?? 2500, attackMs: 50, frontEnergy: 0.3, startDb: -60, endDb: -60, crestDb: 12 } };
  // classify the file name AND its folder (pack folders like "Gorification [HD]" or "Car Destruction" carry the meaning)
  const named = classify(`${pt.folders.join(" ")} - ${file}`, facts);
  const fileOnly = classify(file, facts);
  const category = side?.soundCategory ?? (fileOnly.category !== "other" ? fileOnly.category : named.category);
  const useCases = side?.soundUseCases ?? [...new Set([...fileOnly.useCases, ...named.useCases])];
  return { category, useCases };
}

function musicLike(ws: readonly string[], audio: AudioTech | null | undefined) {
  const m = ["music", "song", "track", "theme", "loop", "melody", "beat", "orchestral", "score"];
  return ws.some((w) => m.includes(w)) && (audio?.durationS == null || audio.durationS >= 8);
}

export function enrichStageA(raw: RawAsset, ctx: StageAContext, side?: SideMeta, measured: Measured = {}): StageAResult {
  const gaps: string[] = [];
  let kind: CatalogKind = KIND_ALIASES[raw.kind] ?? "texture";
  const pt = pathTokens(raw.path, 2);
  const packWords = words(raw.pack).map(canon).filter(isContentWord);
  const upstream = (raw.tags ?? []).flatMap((t) => words(t)).map(canon).filter(isContentWord);
  const sideTags = [...(side?.tags ?? []), ...(side?.themes ?? [])].flatMap((t) => words(t)).map(canon).filter(isContentWord);
  const nameWords = (side?.name ?? raw.name) ? words((side?.name ?? raw.name)!).map(canon) : [];
  const fileContent = pt.file.filter(isContentWord);
  const nameContent = nameWords.filter(isContentWord);
  const audio = measured.audio ?? null;
  if (kind === "sound" && musicLike([...pt.file, ...pt.folders, ...pt.commaTags], audio)) kind = "music";

  // ---- categories -----------------------------------------------------------------------------------------
  const votes: Vote = new Map();
  let primary: string | null = null;
  let confidence = 0.3;
  let soundUseCases: string[] = [];
  if (kind === "sound" || kind === "music") {
    const s = soundSide(raw, pt, side, audio);
    soundUseCases = s.useCases;
    const fromFolder = [...pt.folders, ...pt.commaTags];
    keywordVotes(votes, [...pt.file, ...fromFolder], 2, kind);
    if (kind === "music") { primary = votes.size ? [...votes.entries()].sort((a, b) => b[1] - a[1])[0][0] : "music/score"; confidence = 0.6; }
    else if (s.category !== "other") { primary = `sound/${s.category}`; confidence = side?.soundCategory ? 0.9 : 0.75; }
    else if (votes.size) { primary = [...votes.entries()].sort((a, b) => b[1] - a[1])[0][0]; confidence = 0.6; }
  } else {
    const a1 = aliasOf(raw.category) ?? aliasOf(side?.category && side?.subcategory ? `${side.category}/${side.subcategory}` : side?.category);
    const allowed = (id: string) => DOMAINS[kind].includes(id.split("/")[0]);
    if (a1 && allowed(a1) && !a1.startsWith("tiles/")) vote(votes, a1, 6);
    keywordVotes(votes, nameContent.length ? nameContent : fileContent, 4, kind);
    keywordVotes(votes, [...upstream, ...sideTags], 2, kind);
    keywordVotes(votes, pt.folders, 1.5, kind);
    keywordVotes(votes, packWords, 1, kind);
    if (a1 && allowed(a1) && a1.startsWith("tiles/") && !votes.size) vote(votes, a1, 3); // a generic tileset alias only when nothing better
    if (kind === "hdri" && !votes.size) vote(votes, "env/day-sky", 1);
    const ranked = [...votes.entries()].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1));
    if (ranked.length) {
      primary = ranked[0][0];
      const top = ranked[0][1], second = ranked[1]?.[1] ?? 0;
      confidence = Math.min(0.95, 0.35 + 0.08 * top + (top - second >= 2 ? 0.15 : 0));
      if (a1 === primary) confidence = Math.max(confidence, 0.8);
    }
  }
  if (!primary) {
    primary = kind === "sprite" ? "sprites/general" : kind === "sound" ? "sound/environment_ambience" : kind === "music" ? "music/score" : "misc/uncategorised";
    confidence = 0.15; gaps.push("no category signal");
  }
  const secondary = [...votes.entries()].filter(([id, w]) => id !== primary && w >= 3).sort((a, b) => b[1] - a[1]).slice(0, 3).map(([id]) => id);

  // ---- tags -------------------------------------------------------------------------------------------------
  const tagPool = [...nameContent, ...fileContent, ...pt.commaTags, ...upstream, ...sideTags, ...pt.folders, ...packWords.filter(isControlled)];
  const tagsC: string[] = [], free: string[] = [];
  for (const w of tagPool) {
    const t = slugTag(canon(w));
    if (!t || t.length < 2) continue;
    if (isControlled(t)) { if (!tagsC.includes(t)) tagsC.push(t); }
    else if (!free.includes(t) && /^[a-z]/.test(t)) free.push(t);
  }
  const style = detectStyle([...tagPool, ...packWords], raw, side, kind);
  const add = (t: string) => { if (!tagsC.includes(t)) tagsC.push(t); };
  if (style) add(style);

  // ---- technical facts ---------------------------------------------------------------------------------------
  const tech: Tech = { format: raw.format, bytes: Math.max(0, Math.floor(raw.sizeBytes || 0)) };
  const g = measured.glb;
  if (kind === "model") {
    tech.triangles = g?.triangles ?? raw.triangles ?? null;
    if (g) { tech.vertices = g.vertices; tech.meshes = g.meshes; tech.materials = g.materials; tech.textures = g.textures; tech.bounds = g.bounds; tech.rigged = g.rigged; tech.animations = g.animations; }
    if (g?.rigged) add("rigged");
    if (g && g.animations > 0) add("animated");
  }
  if (kind === "sprite" || kind === "texture" || kind === "decal" || kind === "hdri" || kind === "texture-set") {
    tech.width = measured.image?.width ?? raw.width ?? resolutionPx(raw.resolution);
    tech.height = measured.image?.height ?? raw.height ?? (raw.resolution ? (kind === "hdri" ? (tech.width ?? 0) / 2 : tech.width) : null);
    if (measured.image) tech.hasAlpha = measured.image.hasAlpha;
    if (side?.files?.length) {
      const maps = new Set<string>();
      for (const f of side.files) for (const [re, m] of MAP_PATTERNS) if (re.test(f.replace(/\.[a-z0-9]+$/i, ""))) maps.add(m);
      if (maps.size) tech.maps = [...maps].sort();
    }
    if (side?.physicalSizeM) tech.physicalSizeM = side.physicalSizeM;
    if (kind === "texture-set") { add("pbr"); tech.tileable = true; add("tileable"); }
  }
  if (audio) {
    Object.assign(tech, { durationS: audio.durationS, sampleRate: audio.sampleRate, channels: audio.channels, bitDepth: audio.bitDepth, peakDb: audio.peakDb, truePeakDb: audio.truePeakDb, lufs: audio.lufs, silenceRatio: audio.silenceRatio, loopable: audio.loopable, centroidHz: audio.centroidHz, character: audio.character });
    add(audio.character);
    if (audio.intensity === "soft" || audio.intensity === "loud") add(audio.intensity);
    if (audio.pitchBand !== "mid") add(`${audio.pitchBand}-pitch`);
    if (audio.loopable) add("loopable"); else add("one-shot");
  } else if (kind === "sound" || kind === "music") gaps.push("audio not measured");
  if (kind === "model" && tech.triangles == null) gaps.push("triangles unknown");

  // ---- useFor ------------------------------------------------------------------------------------------------
  const cats = [primary, ...secondary];
  const tagSet = new Set([...tagsC, ...free]);
  const useFor = VOCAB.useFor.filter((u) => {
    if (!u.kinds.includes(kind)) return false;
    const catOk = !u.categoriesAny || u.categoriesAny.some((p) => cats.some((c) => c === p || (p.endsWith("/") && c.startsWith(p))));
    const ucOk = !u.useCasesAny || u.useCasesAny.some((x) => soundUseCases.includes(x));
    const anyOk = !u.tagsAny || u.tagsAny.some((t) => tagSet.has(t));
    const allOk = !u.tagsAll || u.tagsAll.every((t) => tagSet.has(t));
    const styleOk = !u.stylesAny || (style != null && u.stylesAny.includes(style));
    if (!allOk || !styleOk) return false;
    if (u.categoriesAny && u.useCasesAny) return catOk && (ucOk || anyOk);
    if (u.categoriesAny) return catOk && (!u.tagsAny || anyOk || !!u.categoriesAny);
    if (u.useCasesAny) return ucOk || (anyOk && cats.some((c) => c.startsWith("sound/") || c.startsWith("music/")));
    return anyOk;
  }).map((u) => u.id).slice(0, 8);

  // ---- title + description -----------------------------------------------------------------------------------
  const packTitle = ctx.packs?.[raw.pack]?.title ?? raw.pack.replace(/[-_]+/g, " ");
  const strongName = nameContent.length > 0;
  const fileTitleOk = fileContent.length > 0;
  let title: string;
  if (strongName) title = humanTitle(words(side?.name ?? raw.name ?? ""), raw.pack);
  else if (fileTitleOk) title = humanTitle(pt.file, raw.pack);
  else {
    const where = pt.folders.slice(0, 3).join(" ");
    title = humanTitle([...words(packTitle), ...(where ? where.split(" ") : []), ...(pt.number ? [pt.number] : [])], raw.pack);
    gaps.push("opaque file name");
  }
  if (title.length < 2) title = `${kind} ${raw.id.slice(0, 8)}`;
  const desc = describeEntry(kind, title, primary, style, tech, packTitle, useFor);

  // ---- coverage ------------------------------------------------------------------------------------------------
  const titleOk = strongName || fileTitleOk || pt.commaTags.length > 0;
  const catOk = confidence >= 0.5 && !primary.startsWith("misc/") && primary !== "sprites/general";
  let coverage: StageAResult["coverage"] = titleOk && catOk && useFor.length ? "full" : catOk || (titleOk && useFor.length) ? "partial" : "none";
  if (!useFor.length) gaps.push("no situation matched");
  if (!catOk) gaps.push("category not confident");
  if (coverage === "full" && confidence < 0.6) coverage = "partial";

  // ---- licence / legal --------------------------------------------------------------------------------------------
  const tier = TIER_ALIASES[raw.tier] ?? "proprietary-nxeon";
  const legalClass: LegalClass = ctx.legalClass ?? (tier === "user-contributed" ? "user-original" : "platform-library");
  const licenceUrl = raw.licenseUrl ?? null;
  const licence = {
    tier, spdx: raw.licenseSpdx ?? null, sourceUrl: raw.sourceUrl ?? licenceUrl, attribution: raw.attribution ?? null,
    status: ctx.licenceStatus ?? (licenceUrl ? `recorded: licence page ${licenceUrl} (retrieved ${raw.retrievedAt ?? "date unknown"})` : "unverified: no licence source recorded"),
  };
  const thumb = side?.thumbnail ?? raw.thumbnail ?? null;
  const expected = typeof VOCAB.realWorldScale[primary] === "number" ? (VOCAB.realWorldScale[primary] as number) : null;
  const quality = catalogQuality({ kind, tech, licenceDocumented: !!licenceUrl || tier === "user-contributed", hasThumbnail: !!thumb, metadataConfidence: confidence, corrupt: measured.corrupt ?? null, expectedHeightM: expected });
  if (tech.bounds && expected) tech.scaleOk = quality.checks.find((c) => c.id === "scale")?.status === "pass";

  const games = gameFits({ kind, style, tags: tagsC, categories: { primary, secondary }, tech }, ctx.profiles);
  const candidate = {
    schemaVersion: CATALOG_SCHEMA_VERSION, id: raw.id, kind, title, shortDescription: desc,
    tags: tagsC.slice(0, 16), freeTags: free.slice(0, 8), categories: { primary, secondary }, useFor, style, quality, games, tech, licence,
    provenance: { source: raw.source.slice(0, 40), pack: raw.pack.slice(0, 120), path: raw.path.slice(0, 400), retrievedAt: raw.retrievedAt ?? null, via: raw.via ?? raw.upstreamId ?? null, derivedFrom: [] },
    legalClass, contributedBy: tier === "user-contributed" ? ctx.contributedBy ?? null : null,
    status: "pending-checks" as const, statusReason: null, flags: [], group: null, duplicateOf: null, thumbnail: thumb,
    enrichment: { by: "stage-a" as const, confidence: Math.round(confidence * 100) / 100, coverage, model: null, at: ctx.now, gaps: [...new Set(gaps)].slice(0, 8) },
  };
  const v = validateCatalogEntry(candidate);
  return v.ok
    ? { entry: v.entry, errors: [], coverage, gaps: candidate.enrichment.gaps, needsStageB: coverage !== "full" }
    : { entry: null, errors: v.errors, coverage, gaps: candidate.enrichment.gaps, needsStageB: true };
}

const KIND_NOUN: Record<CatalogKind, string> = { model: "3D model", "texture-set": "PBR texture set", texture: "texture", sprite: "sprite", hdri: "HDRI sky", decal: "decal", sound: "sound", music: "music" };

/** Deterministic <= 140-char description: what it is, its category, the key fact, the pack. */
export function describeEntry(kind: CatalogKind, title: string, primary: string, style: string | null, t: Tech, pack: string, useFor: readonly string[]): string {
  const cat = primary.split("/").pop()!.replace(/[-_]/g, " ");
  const st = style ? `${style.replace(/-/g, " ")} ` : "";
  let fact = "";
  if (kind === "model" && t.triangles != null) fact = `${t.triangles.toLocaleString("en-US")} tris${t.animations ? `, ${t.animations} anims` : t.rigged ? ", rigged" : ""}`;
  else if ((kind === "sound" || kind === "music") && t.durationS != null) fact = `${t.durationS < 10 ? t.durationS.toFixed(1) : Math.round(t.durationS)} s${t.loopable ? ", loopable" : ""}`;
  else if (t.width && t.height) fact = `${t.width}x${t.height}${t.maps?.length ? `, ${t.maps.length} maps` : ""}`;
  const use = useFor.length ? `; for ${useForLabel(useFor[0])}` : "";
  const head = `${st}${KIND_NOUN[kind]}: ${title.toLowerCase()} (${cat})`;
  const s = `${head.charAt(0).toUpperCase()}${head.slice(1)}${fact ? `, ${fact}` : ""}${use}. From ${pack}.`;
  return clip(s.length >= 10 ? s : `${s} asset`, 140);
}

/** Sound taxonomy use cases (re-exported so the index and stage B use one list). */
export const SOUND_USE_CASES = SOUND_TAX.useCases.map((u) => u.id);

