// Dedupe + variant grouping, zero tokens.
//   exact      : same id (sha256 of the bytes) -> one entry; the extra rows are reported, not stored
//   near-dup   : same kind + same normalised stem + same size class (+- 1 % bytes, same triangles / pixel size /
//                duration within 10 ms) in a DIFFERENT pack or path -> duplicateOf the best-quality copy
//   variants   : same kind + same stem once colour words and take numbers are removed, in the same pack
//                ("playerBlue_duck" / "playerRed_duck", "tile_0001".."tile_0099") -> one `group` id, so ranking can
//                return ONE representative and stage B can tag a whole group from one contact sheet
// Pure.
import type { CatalogEntry } from "./entry";
import { VOCAB, words, stripExt } from "./vocab";

const COLOURS = new Set([...(VOCAB.tags.color ?? []), "gray", "dark", "light", "colored", "coloured", "alt"]);
const fileStem = (p: string | null) => stripExt((p ?? "").split("/").pop() ?? "");

/** stem with colour words and numbers removed: the variant family key */
export function familyStem(path: string | null): string {
  return words(fileStem(path)).filter((w) => !COLOURS.has(w) && !/^\d+$/.test(w)).join("-") || "n";
}
const exactStem = (path: string | null) => words(fileStem(path)).filter((w) => !/^(copy|final|new)$/.test(w)).join("-");

function sizeClass(e: CatalogEntry): string {
  const t = e.tech;
  if (e.kind === "model") return `t${t.triangles ?? "?"}`;
  if (e.kind === "sound" || e.kind === "music") return `d${t.durationS != null ? Math.round(t.durationS * 100) : "?"}`;
  return `p${t.width ?? "?"}x${t.height ?? "?"}`;
}

export type DedupeReport = { exactDuplicates: number; nearDuplicates: number; groups: number; groupedEntries: number };

export function dedupe(entries: readonly CatalogEntry[]): { entries: CatalogEntry[]; report: DedupeReport } {
  const byId = new Map<string, CatalogEntry>();
  let exact = 0;
  for (const e of entries) { if (byId.has(e.id)) { exact++; continue; } byId.set(e.id, { ...e }); }
  const list = [...byId.values()];

  // near duplicates across packs/paths
  const near = new Map<string, CatalogEntry[]>();
  for (const e of list) {
    const k = `${e.kind}|${exactStem(e.provenance.path)}|${sizeClass(e)}`;
    if (!k.includes("?")) { const a = near.get(k) ?? []; a.push(e); near.set(k, a); }
  }
  let nearN = 0;
  for (const g of near.values()) {
    if (g.length < 2) continue;
    g.sort((a, b) => b.quality.score - a.quality.score || (a.id < b.id ? -1 : 1));
    const best = g[0];
    for (const e of g.slice(1)) {
      const sameBytes = best.tech.bytes && Math.abs(e.tech.bytes - best.tech.bytes) <= best.tech.bytes * 0.01;
      if (sameBytes && e.provenance.path !== best.provenance.path) { e.duplicateOf = best.id; nearN++; }
    }
  }

  // variant families inside one pack
  const fam = new Map<string, CatalogEntry[]>();
  for (const e of list) {
    const k = `${e.kind}|${e.provenance.source}|${e.provenance.pack}|${familyStem(e.provenance.path)}`;
    const a = fam.get(k) ?? []; a.push(e); fam.set(k, a);
  }
  let groups = 0, grouped = 0;
  for (const [k, g] of fam) {
    if (g.length < 2) continue;
    groups++; grouped += g.length;
    const id = `g:${k.split("|").slice(0, 4).join(":")}`.slice(0, 120);
    for (const e of g) e.group = id;
  }
  return { entries: list, report: { exactDuplicates: exact, nearDuplicates: nearN, groups, groupedEntries: grouped } };
}

