// Catalog retrieval: a pluggable index (interface) + the in-memory implementation (pure; tests, single box, and
// the re-ranker every backend shares). ./sqlite-index.ts is the local FTS5 backend; a Postgres or vector backend
// later implements the same CatalogIndex.
//
// Ranking (one function, `rankHit`, used by every backend):
//   text   = sum over query words of (best field weight the word hits) x idf; fields: title 3, useFor 3, tags 2.5,
//            categories 2, free tags 1, description 1. Query words go through BOTH taxonomies' synonym expansion
//            (lib/cyrus/library/search.ts expandTerm). A hit must match >= 60 % of the query words.
//   rank   = textNorm x (0.6 + 0.4 x fitWeight) x (0.75 + 0.25 x quality/100)
//            fitWeight for the asked game: good 1, ok 0.6, unknown 0.35; fit "no" is EXCLUDED unless includeNoFit.
//   filters: status (default published only: held / removed / pending never reach a build), kind, licence tier
//            (by plan), minQuality, tags (all), category prefix, useFor; near-duplicates dropped; one row per
//            variant group (the best one, with the group size).
import { expandTerm, queryWords } from "../search";
import type { CatalogEntry, CatalogKind, CatalogStatus, LicenceTier } from "./entry";
import { canon, useForLabel, words } from "./vocab";

export type CatalogQuery = {
  text?: string;
  kinds?: readonly CatalogKind[];
  game?: string | null;
  minQuality?: number;
  tiers?: readonly LicenceTier[];
  tags?: readonly string[];
  useFor?: readonly string[];
  /** category id or a prefix ending in "/" */
  category?: string;
  statuses?: readonly CatalogStatus[];
  includeNoFit?: boolean;
  collapseGroups?: boolean;
  limit?: number;
  offset?: number;
};
export type CatalogHit = { entry: CatalogEntry; rank: number; text: number; groupSize: number };
export type CatalogSearchResult = { total: number; hits: CatalogHit[]; expanded: string[][] };

export interface CatalogIndex {
  upsert(entries: readonly CatalogEntry[]): Promise<void>;
  remove(ids: readonly string[]): Promise<void>;
  /** full id or a unique hex prefix (>= 8 chars); null when unknown or ambiguous */
  get(idOrPrefix: string): Promise<CatalogEntry | null>;
  search(q: CatalogQuery): Promise<CatalogSearchResult>;
  /** the shortest unique id prefix (>= 12 hex) for a model-facing id */
  shortId(id: string): Promise<string>;
  size(): Promise<number>;
}

export const FIELD_WEIGHTS = { title: 3, useFor: 3, tags: 2.5, categories: 2, freeTags: 1, description: 1 } as const;
type Field = keyof typeof FIELD_WEIGHTS;
export const FIT_WEIGHT = { good: 1, ok: 0.6, unknown: 0.35 } as const;
export const MIN_WORD_SHARE = 0.6;
/** words that only name the KIND of asset, not its content ("prop", "sound") */
const KIND_WORDS: Record<string, CatalogKind[]> = {
  sound: ["sound"], sounds: ["sound"], sfx: ["sound"], audio: ["sound", "music"], music: ["music"], song: ["music"],
  model: ["model"], mesh: ["model"], prop: ["model"], props: ["model"], "3d": ["model"],
  texture: ["texture-set", "texture"], material: ["texture-set"], pbr: ["texture-set"], hdri: ["hdri"], skybox: ["hdri"], sprite: ["sprite"], icon: ["sprite"], decal: ["decal"],
};

export function docFields(e: CatalogEntry): Record<Field, string[]> {
  const w = (s: string) => words(s).map(canon);
  return {
    title: w(e.title),
    useFor: e.useFor.flatMap((u) => [u, ...w(u), ...w(useForLabel(u))]),
    tags: e.tags.flatMap((t) => [t, ...w(t)]),
    categories: [e.categories.primary, ...e.categories.secondary].flatMap((c) => [c, ...w(c)]),
    freeTags: e.freeTags.flatMap((t) => [t, ...w(t)]),
    description: w(e.shortDescription),
  };
}

export type ParsedQuery = { terms: string[][]; kindHints: CatalogKind[] };
export function parseQuery(text: string): ParsedQuery {
  const kindHints = new Set<CatalogKind>();
  const terms: string[][] = [];
  for (const raw of queryWords(text)) {
    const w = canon(raw);
    if (KIND_WORDS[w]) { for (const k of KIND_WORDS[w]) kindHints.add(k); continue; }
    terms.push([...new Set([w, raw, ...expandTerm(w)])]);
  }
  return { terms, kindHints: [...kindHints] };
}

export function passesFilters(e: CatalogEntry, q: CatalogQuery): boolean {
  const statuses = q.statuses ?? ["published"];
  if (!statuses.includes(e.status)) return false;
  if (e.duplicateOf) return false;
  if (q.kinds?.length && !q.kinds.includes(e.kind)) return false;
  if (q.tiers && !q.tiers.includes(e.licence.tier)) return false;
  if (q.minQuality != null && e.quality.score < q.minQuality) return false;
  if (q.tags?.length && !q.tags.every((t) => e.tags.includes(t) || e.freeTags.includes(t))) return false;
  if (q.useFor?.length && !q.useFor.some((u) => e.useFor.includes(u))) return false;
  if (q.category) {
    const cats = [e.categories.primary, ...e.categories.secondary];
    if (!cats.some((c) => (q.category!.endsWith("/") ? c.startsWith(q.category!) : c === q.category))) return false;
  }
  if (q.game && !q.includeNoFit && e.games[q.game]?.fit === "no") return false;
  return true;
}

export function fitWeight(e: CatalogEntry, game: string | null | undefined): number {
  if (!game) return 1;
  const f = e.games[game]?.fit;
  return f === "good" ? FIT_WEIGHT.good : f === "ok" ? FIT_WEIGHT.ok : f === "no" ? 0 : FIT_WEIGHT.unknown;
}
export const rankHit = (textNorm: number, e: CatalogEntry, game: string | null | undefined) => textNorm * (0.6 + 0.4 * fitWeight(e, game)) * (0.75 + 0.25 * (e.quality.score / 100));

/** Text score of one entry: per query word the best field weight it hits (synonyms count), x idf. 0 = too few words matched. */
export function textScore(fields: Record<Field, string[]>, terms: string[][], idf: (t: string) => number): number {
  if (!terms.length) return 1;
  let score = 0, hit = 0;
  const sets = Object.fromEntries(Object.entries(fields).map(([k, v]) => [k, new Set(v)])) as Record<Field, Set<string>>;
  for (const alts of terms) {
    let best = 0, bestTerm = alts[0];
    for (const [f, wgt] of Object.entries(FIELD_WEIGHTS) as [Field, number][]) {
      for (const t of alts) if (sets[f].has(t)) { const v = t === alts[0] ? wgt : wgt * 0.85; if (v > best) { best = v; bestTerm = t; } }
    }
    if (best) { hit++; score += best * idf(bestTerm); }
  }
  return hit / terms.length >= MIN_WORD_SHARE ? score * (hit / terms.length) : 0;
}

/** Group collapse + pagination over already-ranked hits (shared by every backend). */
export function finish(hits: CatalogHit[], q: CatalogQuery): CatalogHit[] {
  hits.sort((a, b) => b.rank - a.rank || b.entry.quality.score - a.entry.quality.score || (a.entry.id < b.entry.id ? -1 : 1));
  let out = hits;
  if (q.collapseGroups !== false) {
    const seen = new Map<string, CatalogHit>();
    out = [];
    for (const h of hits) {
      const g = h.entry.group;
      if (!g) { out.push(h); continue; }
      const first = seen.get(g);
      if (first) { first.groupSize++; continue; }
      seen.set(g, h); out.push(h);
    }
  }
  const off = Math.max(0, Math.floor(q.offset ?? 0)), lim = Math.min(50, Math.max(1, Math.floor(q.limit ?? 8)));
  return out.slice(off, off + lim);
}

export function createMemoryCatalogIndex(initial: readonly CatalogEntry[] = []): CatalogIndex {
  const docs = new Map<string, { e: CatalogEntry; f: Record<Field, string[]> }>();
  const df = new Map<string, number>();
  const bump = (f: Record<Field, string[]>, d: number) => { for (const t of new Set(Object.values(f).flat())) df.set(t, (df.get(t) ?? 0) + d); };
  const put = (e: CatalogEntry) => { const old = docs.get(e.id); if (old) bump(old.f, -1); const f = docFields(e); docs.set(e.id, { e, f }); bump(f, 1); };
  for (const e of initial) put(e);
  const idf = (t: string) => Math.log(1 + (docs.size + 1) / ((df.get(t) ?? 0) + 0.5));
  const byPrefix = (p: string) => { const out: CatalogEntry[] = []; for (const [id, d] of docs) if (id.startsWith(p)) { out.push(d.e); if (out.length > 1) break; } return out; };
  return {
    async upsert(es) { for (const e of es) put(e); },
    async remove(ids) { for (const id of ids) { const d = docs.get(id); if (d) { bump(d.f, -1); docs.delete(id); } } },
    async get(idOrPrefix) {
      const p = idOrPrefix.replace(/^(cat:|c:)/, "").toLowerCase();
      if (!/^[0-9a-f]{8,64}$/.test(p)) return null;
      if (p.length === 64) return docs.get(p)?.e ?? null;
      const m = byPrefix(p);
      return m.length === 1 ? m[0] : null;
    },
    async shortId(id) {
      for (let n = 12; n < 64; n += 2) if (byPrefix(id.slice(0, n)).length <= 1) return id.slice(0, n);
      return id;
    },
    async size() { return docs.size; },
    async search(q) {
      const parsed = parseQuery(q.text ?? "");
      const kinds = q.kinds?.length ? q.kinds : parsed.kindHints.length ? parsed.kindHints : undefined;
      const qq: CatalogQuery = { ...q, kinds };
      const hits: CatalogHit[] = [];
      let max = 0;
      const raw: { e: CatalogEntry; t: number }[] = [];
      for (const { e, f } of docs.values()) {
        if (!passesFilters(e, qq)) continue;
        const t = textScore(f, parsed.terms, idf);
        if (t <= 0) continue;
        raw.push({ e, t }); if (t > max) max = t;
      }
      for (const { e, t } of raw) { const n = max ? t / max : 1; hits.push({ entry: e, text: n, rank: rankHit(n, e, q.game), groupSize: 1 }); }
      const total = hits.length;
      return { total, hits: finish(hits, qq), expanded: parsed.terms };
    },
  };
}

