// Local FTS5 backend of CatalogIndex (SERVER-ONLY: node:sqlite, Node >= 22.13; node-2 runs Node 24). One file or
// ":memory:" database, no extension, no network. FTS5 (porter + unicode61) retrieves candidates with weighted bm25
// over the same fields as the memory index; filters run in SQL; the final order uses the shared rankHit() so every
// backend ranks the same way. Entries are stored as JSON next to the FTS row (the catalog store of record is the
// host's DB; this file is a rebuildable search cache).
import type { CatalogEntry } from "./entry";
import { docFields, finish, parseQuery, passesFilters, rankHit, FIELD_WEIGHTS, type CatalogHit, type CatalogIndex, type CatalogQuery } from "./retrieval";

type Stmt = { run: (...a: unknown[]) => unknown; all: (...a: unknown[]) => unknown[]; get: (...a: unknown[]) => unknown };
type Db = { exec: (sql: string) => void; prepare: (sql: string) => Stmt; close: () => void };

const CANDIDATES = 600;
const ftsQuote = (t: string) => `"${t.replace(/"/g, "")}"`;

export async function createSqliteCatalogIndex(file = ":memory:"): Promise<CatalogIndex & { close(): void }> {
  const mod = (await import("node:sqlite")) as unknown as { DatabaseSync: new (f: string) => Db };
  const db = new mod.DatabaseSync(file);
  db.exec(`
    CREATE TABLE IF NOT EXISTS entry (id TEXT PRIMARY KEY, kind TEXT, status TEXT, tier TEXT, quality INTEGER, dup TEXT, json TEXT NOT NULL);
    CREATE INDEX IF NOT EXISTS entry_kind ON entry(kind, status, tier, quality);
    CREATE VIRTUAL TABLE IF NOT EXISTS entry_fts USING fts5(id UNINDEXED, title, usefor, tags, cats, free, descr, tokenize='porter unicode61');
  `);
  const ins = db.prepare("INSERT OR REPLACE INTO entry (id, kind, status, tier, quality, dup, json) VALUES (?, ?, ?, ?, ?, ?, ?)");
  const delFts = db.prepare("DELETE FROM entry_fts WHERE id = ?");
  const insFts = db.prepare("INSERT INTO entry_fts (id, title, usefor, tags, cats, free, descr) VALUES (?, ?, ?, ?, ?, ?, ?)");
  const del = db.prepare("DELETE FROM entry WHERE id = ?");
  const getOne = db.prepare("SELECT json FROM entry WHERE id = ?");
  const prefix = db.prepare("SELECT id, json FROM entry WHERE id >= ? AND id < ? LIMIT 2");
  const count = db.prepare("SELECT COUNT(*) AS n FROM entry");
  const w = FIELD_WEIGHTS;
  const bm = `bm25(entry_fts, 0, ${w.title}, ${w.useFor}, ${w.tags}, ${w.categories}, ${w.freeTags}, ${w.description})`;
  const upper = (p: string) => p + "g"; // hex prefix range end ("g" sorts after every hex digit)
  const parse = (j: unknown) => JSON.parse(String((j as { json: string }).json)) as CatalogEntry;

  const api: CatalogIndex & { close(): void } = {
    async upsert(es) {
      db.exec("BEGIN");
      try {
        for (const e of es) {
          ins.run(e.id, e.kind, e.status, e.licence.tier, e.quality.score, e.duplicateOf, JSON.stringify(e));
          const f = docFields(e);
          delFts.run(e.id);
          insFts.run(e.id, f.title.join(" "), f.useFor.join(" "), f.tags.join(" "), f.categories.join(" "), f.freeTags.join(" "), f.description.join(" "));
        }
        db.exec("COMMIT");
      } catch (err) { db.exec("ROLLBACK"); throw err; }
    },
    async remove(ids) { for (const id of ids) { del.run(id); delFts.run(id); } },
    async get(idOrPrefix) {
      const p = idOrPrefix.replace(/^(cat:|c:)/, "").toLowerCase();
      if (!/^[0-9a-f]{8,64}$/.test(p)) return null;
      if (p.length === 64) { const r = getOne.get(p); return r ? parse(r) : null; }
      const rows = prefix.all(p, upper(p));
      return rows.length === 1 ? parse(rows[0]) : null;
    },
    async shortId(id) {
      for (let n = 12; n < 64; n += 2) if (prefix.all(id.slice(0, n), upper(id.slice(0, n))).length <= 1) return id.slice(0, n);
      return id;
    },
    async size() { return Number((count.get() as { n: number }).n); },
    async search(q: CatalogQuery) {
      const parsed = parseQuery(q.text ?? "");
      const kinds = q.kinds?.length ? q.kinds : parsed.kindHints.length ? parsed.kindHints : undefined;
      const qq: CatalogQuery = { ...q, kinds };
      const statuses = qq.statuses ?? ["published"];
      const where: string[] = [`e.status IN (${statuses.map(() => "?").join(",")})`, "e.dup IS NULL"];
      const args: unknown[] = [...statuses];
      if (kinds?.length) { where.push(`e.kind IN (${kinds.map(() => "?").join(",")})`); args.push(...kinds); }
      if (qq.tiers) { where.push(`e.tier IN (${qq.tiers.map(() => "?").join(",") || "''"})`); args.push(...qq.tiers); }
      if (qq.minQuality != null) { where.push("e.quality >= ?"); args.push(qq.minQuality); }
      let rows: { json: string; s: number }[];
      if (parsed.terms.length) {
        const match = parsed.terms.map((alts) => `(${alts.map(ftsQuote).join(" OR ")})`).join(" OR ");
        rows = db.prepare(`SELECT e.json AS json, ${bm} AS s FROM entry_fts JOIN entry e ON e.id = entry_fts.id WHERE entry_fts MATCH ? AND ${where.join(" AND ")} ORDER BY s LIMIT ${CANDIDATES}`).all(match, ...args) as { json: string; s: number }[];
      } else {
        rows = db.prepare(`SELECT e.json AS json, 0 AS s FROM entry e WHERE ${where.join(" AND ")} ORDER BY e.quality DESC LIMIT ${CANDIDATES}`).all(...args) as { json: string; s: number }[];
      }
      // bm25 is negative-better; require the same >= 60 % word share as the memory index (FTS OR-matching is wider)
      const hits: CatalogHit[] = [];
      let best = 0;
      const cand: { e: CatalogEntry; t: number }[] = [];
      for (const r of rows) {
        const e = JSON.parse(r.json) as CatalogEntry;
        if (!passesFilters(e, qq)) continue;
        if (parsed.terms.length) {
          const f = docFields(e);
          const all = new Set(Object.values(f).flat());
          const share = parsed.terms.filter((alts) => alts.some((t) => all.has(t))).length / parsed.terms.length;
          if (share < 0.6) continue;
          const t = -r.s * share;
          cand.push({ e, t }); if (t > best) best = t;
        } else cand.push({ e, t: 1 });
      }
      for (const { e, t } of cand) { const n = best ? Math.max(0, t / best) : 1; hits.push({ entry: e, text: n, rank: rankHit(n, e, q.game), groupSize: 1 }); }
      return { total: hits.length, hits: finish(hits, qq), expanded: parsed.terms };
    },
    close() { db.close(); },
  };
  return api;
}

