// The MODEL-FACING tool contract of the catalog, for the build service (Claude picks assets by calling these):
//   catalog_search(query, kind?, game?, minQuality?, limit<=8) -> compact rows, hard-capped at ~1k tokens
//   catalog_get(id)                                            -> one entry's detail (~250-400 tokens) + its `ref`
// A picked asset goes into a ModSpec asset slot as { source: "library", libraryRef: "cat:<sha256>" }
// (lib/cyrus/engine-core/spec.ts); resolveLibrarySlot() is what the build service runs on every such slot.
// Gates (server-side, every call): the plan-tier asset gate (lib/cyrus/engine-core/asset-gate.ts canAsset(plan,
// kind, "create"): picking from a library creates content), the licence tiers the plan may use (PLAN_TIERS, owner
// decision), the proprietary-library clearance flag (same fail-closed rule as CYRUS_SOUND_LIBRARY_CLEARED), and
// status = published. HOST SEAM: the host passes plan + flags in ToolContext; nothing here reads Nxeon state.
import { canAsset, normalizePlan, type AssetPlan } from "../../engine-core/asset-gate";
import type { AssetSlot } from "../../engine-core/spec";
import { CATALOG_KINDS, CATALOG_REF_RE, catalogRef, gateKindOf, type CatalogEntry, type CatalogKind, type LicenceTier } from "./entry";
import type { CatalogIndex } from "./retrieval";
import { useForLabel } from "./vocab";

export const SEARCH_LIMIT_MAX = 8;
/** hard ceiling for one tool result; ~4 chars per token for this JSON => ~1k tokens (measured: see test) */
export const RESULT_CHAR_BUDGET = 3800;

/**
 * Licence tiers each plan may pick from (OWNER DECISION, defaults below). proprietary-nxeon additionally needs the
 * host's clearance flag, because the owner's bought libraries forbid redistribution and must be transformed.
 */
export const PLAN_TIERS: Readonly<Record<AssetPlan, readonly LicenceTier[]>> = {
  free: [], katara: [],
  saka: ["cc0", "cc-by", "user-contributed", "proprietary-nxeon"],
  all: ["cc0", "cc-by", "user-contributed", "proprietary-nxeon"],
};

export type ToolContext = {
  index: CatalogIndex;
  /** raw plan from the host (any spelling asset-gate understands); unknown -> fail closed */
  plan: unknown;
  /** the project's game (default for `game`) */
  game: string | null;
  /** host flag: the owner cleared the proprietary library for customer builds */
  proprietaryCleared: boolean;
};

export const CATALOG_TOOLS = [
  {
    name: "catalog_search",
    description: "Search Nxeon's asset catalog (3D models, PBR textures, sprites, HDRIs, decals, sounds, music) for an asset to use in this mod. Describe the situation, not a file name: e.g. 'weapon pickup sound', 'sci-fi crate prop', 'stone wall floor texture'. Results are ranked by fit for the game, quality and relevance; only assets your plan can use are returned. Use catalog_get on a result before putting it into an asset slot.",
    input_schema: {
      type: "object",
      additionalProperties: false,
      required: ["query"],
      properties: {
        query: { type: "string", minLength: 2, maxLength: 120, description: "what the asset is for, in plain words" },
        kind: { type: "string", enum: [...CATALOG_KINDS], description: "optional asset kind" },
        game: { type: "string", description: "game id; defaults to the project's game" },
        minQuality: { type: "integer", minimum: 0, maximum: 100, description: "minimum quality score (default 40)" },
        limit: { type: "integer", minimum: 1, maximum: SEARCH_LIMIT_MAX, description: "rows to return (default 6, max 8)" },
      },
    },
  },
  {
    name: "catalog_get",
    description: "Get one catalog asset by the id catalog_search returned: technical facts, game fit with budget notes, licence and the `ref` to put in a ModSpec asset slot as { source: \"library\", libraryRef: ref }.",
    input_schema: {
      type: "object",
      additionalProperties: false,
      required: ["id"],
      properties: { id: { type: "string", pattern: "^(c:|cat:)?[0-9a-f]{12,64}$", description: "id from catalog_search" } },
    },
  },
] as const;

export type ToolResult = { ok: boolean; content: string; chars: number };
const out = (ok: boolean, body: unknown): ToolResult => { const content = JSON.stringify(body); return { ok, content, chars: content.length }; };

/** Kinds this plan may use + the tiers it may pick from (both empty = nothing). */
export function access(plan: unknown, proprietaryCleared: boolean): { kinds: CatalogKind[]; tiers: LicenceTier[]; plan: AssetPlan | null } {
  const p = normalizePlan(plan);
  if (!p) return { kinds: [], tiers: [], plan: null };
  const kinds = CATALOG_KINDS.filter((k) => canAsset(p, gateKindOf(k), "create").ok);
  const tiers = PLAN_TIERS[p].filter((t) => t !== "proprietary-nxeon" || proprietaryCleared);
  return { kinds, tiers: [...tiers], plan: p };
}

const keyFact = (e: CatalogEntry): Record<string, number> => {
  const t = e.tech;
  if (e.kind === "model" && t.triangles != null) return { tris: t.triangles };
  if ((e.kind === "sound" || e.kind === "music") && t.durationS != null) return { sec: Math.round(t.durationS * 10) / 10 };
  if (t.width) return { px: t.width };
  return {};
};

/** One compact search row (~45-70 tokens). */
export async function compactRow(e: CatalogEntry, game: string | null, index: CatalogIndex, groupSize = 1): Promise<Record<string, unknown>> {
  const fit = game ? e.games[game]?.fit ?? "unknown" : undefined;
  return {
    id: `c:${await index.shortId(e.id)}`, t: e.title, d: e.shortDescription, k: e.kind,
    tags: e.tags.filter((x) => x !== e.style).slice(0, 5), ...(fit ? { fit } : {}), q: e.quality.score, ...keyFact(e),
    ...(groupSize > 1 ? { variants: groupSize } : {}),
  };
