  let body: Record<string, unknown> = { n: r.total, game, rows };
  if (JSON.stringify(body).length > RESULT_CHAR_BUDGET) body = { ...body, rows: rows.map(({ d: _d, ...x }) => x) };
  while (JSON.stringify(body).length > RESULT_CHAR_BUDGET && (body.rows as unknown[]).length > 1) body = { ...body, rows: (body.rows as unknown[]).slice(0, -1) };
