export async function catalogGet(input: { id?: unknown }, ctx: ToolContext): Promise<ToolResult> {
  const id = typeof input.id === "string" ? input.id : "";
  const e = await ctx.index.get(id);
  const a = access(ctx.plan, ctx.proprietaryCleared);
  // an entry the caller may not use is reported as not found (no metadata leak across gates)
  if (!e || e.status !== "published" || !a.kinds.includes(e.kind) || !a.tiers.includes(e.licence.tier)) return out(false, { error: "not_found" });
  const t = e.tech;
  const tech = Object.fromEntries(Object.entries({
    format: t.format, tris: t.triangles, bounds_m: t.bounds, rigged: t.rigged, anims: t.animations, materials: t.materials,
    px: t.width && t.height ? `${t.width}x${t.height}` : null, maps: t.maps, tileable: t.tileable, sec: t.durationS, hz: t.sampleRate, ch: t.channels, lufs: t.lufs, loop: t.loopable,
  }).filter(([, v]) => v != null && !(Array.isArray(v) && !v.length)));
  const fit = ctx.game ? e.games[ctx.game] ?? null : null;
  return out(true, {
    ref: catalogRef(e.id), t: e.title, d: e.shortDescription, k: e.kind, cat: e.categories.primary, style: e.style,
    tags: e.tags.slice(0, 10), useFor: e.useFor.map(useForLabel).slice(0, 4), q: e.quality.score,
    fails: e.quality.checks.filter((c) => c.status === "fail").map((c) => c.id),
    ...(fit ? { fit: { game: ctx.game, fit: fit.fit, why: fit.reason, notes: fit.notes, transform: fit.transform } } : { fit: { game: ctx.game, fit: "unknown" } }),
    tech, licence: { tier: e.licence.tier, spdx: e.licence.spdx, attribution: e.licence.attribution },
    ...(e.licence.tier === "proprietary-nxeon" ? { rule: "proprietary library: ship transformed (pitch/edit), never the original file" } : {}),
  });
}

export async function handleCatalogTool(name: string, input: unknown, ctx: ToolContext): Promise<ToolResult> {
  const i = (input && typeof input === "object" ? input : {}) as Record<string, unknown>;
  if (name === "catalog_search") return catalogSearch(i, ctx);
  if (name === "catalog_get") return catalogGet(i, ctx);
  return out(false, { error: `unknown tool ${name}` });
}

export type SlotDecision = { ok: true; entry: CatalogEntry; transform: string[] } | { ok: false; code: "not_library" | "bad_ref" | "not_found" | "not_published" | "kind_mismatch" | "asset_locked" | "tier_locked" | "no_fit"; reason: string };

/** What the build service runs for a ModSpec asset slot with source "library" (after gateSpecAssets). */
export async function resolveLibrarySlot(slot: Pick<AssetSlot, "id" | "kind" | "source"> & { libraryRef?: string }, ctx: ToolContext): Promise<SlotDecision> {
  if (slot.source !== "library") return { ok: false, code: "not_library", reason: `slot ${slot.id} is not a library slot` };
  if (!slot.libraryRef || !CATALOG_REF_RE.test(slot.libraryRef)) return { ok: false, code: "bad_ref", reason: `slot ${slot.id} needs libraryRef cat:<sha256>` };
  const e = await ctx.index.get(slot.libraryRef.slice(4));
  if (!e) return { ok: false, code: "not_found", reason: `${slot.libraryRef} is not in the catalog` };
  if (e.status !== "published") return { ok: false, code: "not_published", reason: `${slot.libraryRef} is ${e.status}` };
  const want = gateKindOf(e.kind);
  if (!(want === slot.kind || (slot.kind === "ui" && want === "texture"))) return { ok: false, code: "kind_mismatch", reason: `slot ${slot.id} is ${slot.kind}, the asset is a ${e.kind}` };
  const d = canAsset(ctx.plan, slot.kind, "create");
  if (!d.ok) return { ok: false, code: "asset_locked", reason: d.reason };
  const a = access(ctx.plan, ctx.proprietaryCleared);
  if (!a.tiers.includes(e.licence.tier)) return { ok: false, code: "tier_locked", reason: `${e.licence.tier} assets are not available on this plan${e.licence.tier === "proprietary-nxeon" && !ctx.proprietaryCleared ? " (library not cleared)" : ""}` };
  const fit = ctx.game ? e.games[ctx.game] : undefined;
  if (fit?.fit === "no") return { ok: false, code: "no_fit", reason: fit.reason };
  return { ok: true, entry: e, transform: fit?.transform ?? [] };
}

