export const DEFAULT_TOKEN_MODEL: TokenModel = { charsPerToken: 3.6, imageTokens: (w, h) => Math.ceil((w * h) / 750), outputTokensPerAsset: 42, outputOverheadPerCall: 12 };

export type StageBBatch = { kind: "sheet" | "audio"; entries: CatalogEntry[]; /** entries that inherit the result of entries[i] */ followers: CatalogEntry[][]; prompt: string; imagePx: [number, number] | null };
export type StageBPlan = { batches: StageBBatch[]; assets: number; represented: number; skippedFull: number; skippedNoThumb: number; system: string };

/** The fixed instruction + vocabulary prefix (identical for every call of a run). */
export function stageBSystem(): string {
  const cats = CATEGORY_IDS.join(" ");
  const uses = USE_FOR_IDS.join(" ");
  return [
    "You tag game assets for a searchable catalog. For each numbered cell return ONE JSON object per line:",
    '{"i":<cell>,"t":"<title, 2-6 words>","d":"<what it is, <=100 chars>","c":"<category id>","tags":["<3-8 lowercase tags>"],"u":["<0-3 situation ids>"],"s":"<style id or null>","p":<0-1 confidence>}',
    "Use only the category, situation and style ids below; tags may be any short lowercase words. Describe only what you see or hear; if unsure, lower p. No prose.",
    `categories: ${cats}`,
    `situations: ${uses}`,
    `styles: ${VOCAB.styles.join(" ")}`,
  ].join("\n");
}

function cellLine(i: number, e: CatalogEntry): string {
  const t = e.tech;
  const fact = e.kind === "model" ? `${t.triangles ?? "?"} tris` : e.kind === "sound" || e.kind === "music"
    ? `${t.durationS ?? "?"}s ${t.channels ?? "?"}ch ${t.lufs ?? "?"}LUFS ${t.character ?? ""} centroid ${t.centroidHz ?? "?"}Hz${t.loopable ? " loopable" : ""}`
    : `${t.width ?? "?"}x${t.height ?? "?"}`;
  return `${i}: ${e.kind} | ${(e.provenance.path ?? "").split("/").slice(1).join("/")} | ${fact}`;
}

export function planStageB(entries: readonly CatalogEntry[], opts: { sheet?: SheetSpec; hasThumbnail?: (e: CatalogEntry) => boolean } = {}): StageBPlan {
  const sheet = opts.sheet ?? DEFAULT_SHEET;
  const hasThumb = opts.hasThumbnail ?? ((e: CatalogEntry) => !!e.thumbnail);
  const todo = entries.filter((e) => e.enrichment.coverage !== "full" && !e.duplicateOf && e.status !== "removed");
  const skippedFull = entries.length - todo.length;
  // one representative per variant group
  const reps = new Map<string, { rep: CatalogEntry; followers: CatalogEntry[] }>();
  for (const e of todo) {
    const k = e.group ?? `id:${e.id}`;
    const r = reps.get(k);
    if (!r) reps.set(k, { rep: e, followers: [] }); else r.followers.push(e);
  }
  const visual: { rep: CatalogEntry; followers: CatalogEntry[] }[] = [], audio: typeof visual = [];
  let noThumb = 0;
  for (const r of reps.values()) {
    if (r.rep.kind === "sound" || r.rep.kind === "music") audio.push(r);
    else if (VISUAL_KINDS.includes(r.rep.kind)) { if (hasThumb(r.rep)) visual.push(r); else noThumb++; }
  }
  const batches: StageBBatch[] = [];
  const rows = Math.ceil(sheet.cells / sheet.columns);
  for (let i = 0; i < visual.length; i += sheet.cells) {
    const chunk = visual.slice(i, i + sheet.cells);
    batches.push({ kind: "sheet", entries: chunk.map((c) => c.rep), followers: chunk.map((c) => c.followers), prompt: chunk.map((c, j) => cellLine(j + 1, c.rep)).join("\n"), imagePx: [sheet.columns * sheet.cellPx, rows * sheet.cellPx] });
  }
  for (let i = 0; i < audio.length; i += AUDIO_ROWS_PER_CALL) {
    const chunk = audio.slice(i, i + AUDIO_ROWS_PER_CALL);
    batches.push({ kind: "audio", entries: chunk.map((c) => c.rep), followers: chunk.map((c) => c.followers), prompt: chunk.map((c, j) => cellLine(j + 1, c.rep)).join("\n"), imagePx: null });
  }
  return { batches, assets: todo.length, represented: visual.length + audio.length, skippedFull, skippedNoThumb: noThumb, system: stageBSystem() };
}

export type Prices = { inputPerMTok: number; outputPerMTok: number; cacheReadPerMTok?: number; batchDiscount?: number };
export type CostEstimate = { calls: number; assets: number; represented: number; inputTokens: number; cachedPrefixTokens: number; outputTokens: number; dollars: number | null; assumptions: string[] };

export function batchTokens(b: StageBBatch, system: string, tm: TokenModel = DEFAULT_TOKEN_MODEL): { input: number; prefix: number; output: number } {
  const prefix = Math.ceil(system.length / tm.charsPerToken);
  const text = Math.ceil(b.prompt.length / tm.charsPerToken);
  const img = b.imagePx ? tm.imageTokens(b.imagePx[0], b.imagePx[1]) : 0;
  return { input: prefix + text + img, prefix, output: tm.outputOverheadPerCall + b.entries.length * tm.outputTokensPerAsset };
}

/** Dry-run cost estimator: expected tokens (and dollars when prices are given) for a plan. Never calls a model. */
export function estimateStageB(plan: StageBPlan, prices: Prices | null = null, tm: TokenModel = DEFAULT_TOKEN_MODEL): CostEstimate {
  let input = 0, prefix = 0, output = 0;
  for (const b of plan.batches) { const t = batchTokens(b, plan.system, tm); input += t.input; prefix += t.prefix; output += t.output; }
  let dollars: number | null = null;
  if (prices) {
    const cached = prices.cacheReadPerMTok != null ? Math.max(0, prefix - (plan.batches.length ? Math.ceil(plan.system.length / tm.charsPerToken) : 0)) : 0; // first call writes the cache
    const fresh = input - cached;
    const d = (fresh * prices.inputPerMTok + cached * (prices.cacheReadPerMTok ?? prices.inputPerMTok) + output * prices.outputPerMTok) / 1e6;
    dollars = Math.round(d * (1 - (prices.batchDiscount ?? 0)) * 100) / 100;
  }
  return {
    calls: plan.batches.length, assets: plan.assets, represented: plan.represented, inputTokens: input, cachedPrefixTokens: prefix, outputTokens: output, dollars,
    assumptions: [`text ${tm.charsPerToken} chars/token`, "image tokens = w*h/750", `${tm.outputTokensPerAsset} output tokens/asset + ${tm.outputOverheadPerCall}/call`, "prices are inputs; null = tokens only"],
  };
}

const ResultLineZ = z.object({
  i: z.number().int().min(1),
  t: z.string().min(2).max(80),
  d: z.string().min(5).max(200),
  c: z.string().max(60),
  tags: z.array(z.string().max(32)).max(12),
  u: z.array(z.string().max(48)).max(4).default([]),
  s: z.string().max(24).nullable().default(null),
  p: z.number().min(0).max(1),
});
export type TagLine = z.infer<typeof ResultLineZ>;

/** Parse a model reply: one JSON object per line; bad lines are dropped and counted, never trusted. */
export function parseTagReply(text: string): { lines: TagLine[]; rejected: number } {
  const lines: TagLine[] = [];
  let rejected = 0;
  for (const raw of text.split("\n")) {
    const s = raw.trim();
    if (!s.startsWith("{")) continue;
    try { const r = ResultLineZ.safeParse(JSON.parse(s)); if (r.success) lines.push(r.data); else rejected++; } catch { rejected++; }
  }
  return { lines, rejected };
}

/** Merge one tag line into an entry (vocabulary-checked). Returns null when the line is unusable. */
export function mergeTagLine(e: CatalogEntry, l: TagLine, model: string, now: string, follower = false): CatalogEntry | null {
  const domainOk = CATEGORY_IDS.includes(l.c);
  const tags = [...new Set(l.tags.map((t) => slugTag(t)).filter((t) => t.length >= 2))];
  const ctl = tags.filter(isControlled), free = tags.filter((t) => !isControlled(t));
  const useFor = l.u.filter((u) => USE_FOR_IDS.includes(u));
  const style = l.s && VOCAB.styles.includes(l.s) ? l.s : e.style;
  const num = follower ? (e.provenance.path ?? "").match(/(\d{1,5})(?=\.[a-z0-9]+$)/i)?.[1] : null;
  const title = clip(num ? `${l.t} ${num}` : l.t, 80);
  const confidence = Math.min(l.p, domainOk ? 1 : 0.3) * (follower ? 0.9 : 1);
  const next = {
    ...e, title, shortDescription: clip(l.d.length >= 10 ? l.d : `${l.d} (${e.kind})`, 140),
    tags: [...new Set([...ctl, ...e.tags])].slice(0, 16), freeTags: [...new Set([...free, ...e.freeTags])].slice(0, 8),
    categories: domainOk ? { primary: l.c, secondary: [e.categories.primary, ...e.categories.secondary].filter((c) => c !== l.c).slice(0, 3) } : e.categories,
    useFor: [...new Set([...useFor, ...e.useFor])].slice(0, 8), style,
    enrichment: { ...e.enrichment, by: "stage-b" as const, model, at: now, confidence: Math.round(confidence * 100) / 100, coverage: (domainOk && confidence >= 0.6 && useFor.length ? "full" : "partial") as "full" | "partial", gaps: domainOk ? [] : ["stage-b category not in vocabulary"] },
  };
  const v = validateCatalogEntry(next);
  return v.ok ? v.entry : null;
}

export type TagRequest = { model: string; system: string; prompt: string; imagePx: [number, number] | null; batch: StageBBatch; maxOutputTokens: number };
export interface TaggerClient {
  /** the host renders the contact sheet for `batch` and calls the model; returns the text and the real usage */
  tag(req: TagRequest): Promise<{ text: string; usage: { inputTokens: number; outputTokens: number } }>;
}
export type Budget = { maxInputTokens: number; maxOutputTokens: number };
export type RunReport = { status: "done" | "dry_run" | "budget_exhausted" | "error"; calls: number; usage: { inputTokens: number; outputTokens: number }; updated: CatalogEntry[]; rejectedLines: number; stoppedAt: number | null; estimate: CostEstimate; error?: string };

/** Run (or dry-run) stage B under a HARD token budget. Stops before a call whose estimate would exceed what is left. */
export async function runStageB(plan: StageBPlan, client: TaggerClient | null, opts: { tier: StageBTier; budget: Budget; dryRun: boolean; now: string; prices?: Prices | null; tokenModel?: TokenModel }): Promise<RunReport> {
  const tm = opts.tokenModel ?? DEFAULT_TOKEN_MODEL;
  const estimate = estimateStageB(plan, opts.prices ?? null, tm);
  const usage = { inputTokens: 0, outputTokens: 0 };
  const updated: CatalogEntry[] = [];
  if (opts.dryRun || !client) return { status: "dry_run", calls: 0, usage, updated, rejectedLines: 0, stoppedAt: null, estimate };
  if (!(opts.budget.maxInputTokens > 0 && opts.budget.maxOutputTokens > 0)) return { status: "budget_exhausted", calls: 0, usage, updated, rejectedLines: 0, stoppedAt: 0, estimate };
  const model = STAGE_B_TIERS[opts.tier].model;
  let rejected = 0, calls = 0;
  for (let bi = 0; bi < plan.batches.length; bi++) {
    const b = plan.batches[bi];
    const t = batchTokens(b, plan.system, tm);
    if (usage.inputTokens + t.input > opts.budget.maxInputTokens || usage.outputTokens + t.output > opts.budget.maxOutputTokens) {
      return { status: "budget_exhausted", calls, usage, updated, rejectedLines: rejected, stoppedAt: bi, estimate };
    }
    let reply: Awaited<ReturnType<TaggerClient["tag"]>>;
    try { reply = await client.tag({ model, system: plan.system, prompt: b.prompt, imagePx: b.imagePx, batch: b, maxOutputTokens: Math.ceil(t.output * 1.5) }); }
    catch (err) { return { status: "error", calls, usage, updated, rejectedLines: rejected, stoppedAt: bi, estimate, error: String((err as Error)?.message ?? err).slice(0, 200) }; }
    calls++;
    usage.inputTokens += Math.max(0, reply.usage.inputTokens); usage.outputTokens += Math.max(0, reply.usage.outputTokens);
    const p = parseTagReply(reply.text);
    rejected += p.rejected;
    for (const l of p.lines) {
      const e = b.entries[l.i - 1];
      if (!e) { rejected++; continue; }
      const m = mergeTagLine(e, l, model, opts.now);
      if (m) updated.push(m); else rejected++;
      for (const f of b.followers[l.i - 1] ?? []) { const mf = mergeTagLine(f, l, model, opts.now, true); if (mf) updated.push(mf); }
    }
    if (usage.inputTokens > opts.budget.maxInputTokens || usage.outputTokens > opts.budget.maxOutputTokens) return { status: "budget_exhausted", calls, usage, updated, rejectedLines: rejected, stoppedAt: bi + 1, estimate };
  }
  return { status: "done", calls, usage, updated, rejectedLines: rejected, stoppedAt: null, estimate };
}

