// Enrichment STAGE C: owner / human spot-check. Produces the DATA a review screen needs (no UI here):
//   sampleForReview(): a stratified, seeded, reproducible sample per (kind, enrichment stage, coverage) stratum,
//                      sized so each stratum's error rate is known to about +-10 points (n ~ 30 per stratum, capped)
//   reviewRow():       one compact card (thumbnail ref, title, description, tags, categories, situations, fits)
//                      plus the questions the reviewer answers (title ok? category ok? situations ok? fit ok?)
//   precisionByStratum(): from verdicts, the share of correct fields per stratum with a Wilson 95 % interval;
//                      a stratum below the bar (default 0.85 on category) marks its stage's output for HOLD/rework
// Pure; verdicts are stored by the host (CyrusCatalogReview), reviewer ids are opaque.
import type { CatalogEntry } from "./entry";
import { useForLabel } from "./vocab";

export type Stratum = string;
export const stratumOf = (e: CatalogEntry): Stratum => `${e.kind}|${e.enrichment.by}|${e.enrichment.coverage}`;

/** Deterministic PRNG (mulberry32) so a sample can be re-drawn exactly. */
function rng(seed: number) { let a = seed >>> 0; return () => { a = (a + 0x6d2b79f5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }

export function sampleForReview(entries: readonly CatalogEntry[], opts: { perStratum?: number; seed?: number; maxTotal?: number } = {}): CatalogEntry[] {
  const per = opts.perStratum ?? 30, rand = rng(opts.seed ?? 20261010), max = opts.maxTotal ?? 600;
  const by = new Map<Stratum, CatalogEntry[]>();
  for (const e of entries) { if (e.status === "removed" || e.duplicateOf) continue; const s = stratumOf(e); const a = by.get(s) ?? []; a.push(e); by.set(s, a); }
  const out: CatalogEntry[] = [];
  for (const s of [...by.keys()].sort()) {
    const a = [...by.get(s)!].sort((x, y) => (x.id < y.id ? -1 : 1));
    for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
    out.push(...a.slice(0, per));
  }
  return out.slice(0, max);
}

export const REVIEW_FIELDS = ["title", "category", "useFor", "tags", "fit"] as const;
export type ReviewField = (typeof REVIEW_FIELDS)[number];

export type ReviewRow = {
  id: string; stratum: Stratum; thumbnail: string | null; kind: string; title: string; description: string; category: string; secondary: string[];
  tags: string[]; useFor: string[]; style: string | null; quality: number; fits: Record<string, string>; source: string; enrichedBy: string; confidence: number;
  questions: { field: ReviewField; prompt: string }[];
};
export function reviewRow(e: CatalogEntry): ReviewRow {
  return {
    id: e.id, stratum: stratumOf(e), thumbnail: e.thumbnail, kind: e.kind, title: e.title, description: e.shortDescription,
    category: e.categories.primary, secondary: e.categories.secondary, tags: e.tags, useFor: e.useFor.map(useForLabel), style: e.style,
    quality: e.quality.score, fits: Object.fromEntries(Object.entries(e.games).map(([g, f]) => [g, `${f.fit}: ${f.reason}`])),
    source: `${e.provenance.source}/${e.provenance.pack ?? ""}`, enrichedBy: e.enrichment.by, confidence: e.enrichment.confidence,
    questions: [
      { field: "title", prompt: "Does the title say what this is?" },
      { field: "category", prompt: "Is the primary category right?" },
      { field: "useFor", prompt: "Would you pick it for these situations (or is a situation missing)?" },
      { field: "tags", prompt: "Are the tags right (no wrong tag)?" },
      { field: "fit", prompt: "Is the game fit right?" },
    ],
  };
}

export type Verdict = { entryId: string; stratum: Stratum; reviewer: string; answers: Partial<Record<ReviewField, boolean>>; corrections?: Partial<{ title: string; category: string; useFor: string[]; tags: string[] }>; at: string };

export function wilson(ok: number, n: number, z = 1.96): [number, number] {
  if (!n) return [0, 1];
  const p = ok / n, d = 1 + (z * z) / n, c = p + (z * z) / (2 * n), m = z * Math.sqrt((p * (1 - p)) / n + (z * z) / (4 * n * n));
  return [Math.max(0, (c - m) / d), Math.min(1, (c + m) / d)];
}

export type StratumPrecision = { stratum: Stratum; n: number; fields: Record<string, { ok: number; n: number; rate: number; ci95: [number, number] }>; belowBar: boolean };
export function precisionByStratum(verdicts: readonly Verdict[], bar: { field: ReviewField; min: number } = { field: "category", min: 0.85 }): StratumPrecision[] {
  const by = new Map<Stratum, Verdict[]>();
  for (const v of verdicts) { const a = by.get(v.stratum) ?? []; a.push(v); by.set(v.stratum, a); }
  return [...by.entries()].sort().map(([stratum, vs]) => {
    const fields: StratumPrecision["fields"] = {};
    for (const f of REVIEW_FIELDS) {
      const ans = vs.map((v) => v.answers[f]).filter((x): x is boolean => typeof x === "boolean");
      const ok = ans.filter(Boolean).length;
      fields[f] = { ok, n: ans.length, rate: ans.length ? Math.round((ok / ans.length) * 1000) / 1000 : 0, ci95: wilson(ok, ans.length).map((x) => Math.round(x * 1000) / 1000) as [number, number] };
    }
    const b = fields[bar.field];
    return { stratum, n: vs.length, fields, belowBar: b.n >= 10 && b.rate < bar.min };
  });
}

