// Catalog v2 pipeline + host seams.
//   CatalogStore     : the store of record (host implements it on the Cyrus-prefixed tables of the migration
//                      prisma/manual-migrations/2026-10-10-cyrus-catalog-v2.sql); memory version for tests.
//   ingestRows()     : raw rows -> stage A -> dedupe/variant groups -> content filters -> status -> store + index.
//   contribute()     : a Cyrus user's generated/authored asset -> pending-checks -> strict filters -> published/held.
//   builtinEntries() : the existing libraries (owner sound library manifest, Cyrus texture templates) as entries,
//                      so EVERY library flows through one catalog.
//   catalogProvider(): a LibraryProvider (lib/cyrus/library/types.ts) over the index, so browseLibrary() and the
//                      studios' search keep working unchanged on top of the v2 catalog.
// HOST SEAM: no Nxeon imports; ids are content hashes, contributors opaque.
import type { AssetProfile } from "../../adapters/asset-profile";
import { librarySounds, type LibrarySound } from "../../sound/library";
import { libraryTextures } from "../../texture-library/library";
