import type { CatalogEntry, CatalogStatus } from "./entry";
import { libraryKindOf } from "./entry";
import { dedupe, type DedupeReport } from "./dedupe";
import { applyDecision, runContentFilters, type ContentFilter, type FilterContext } from "./filters";
import type { CatalogIndex } from "./retrieval";
import { enrichStageA, type Measured, type PackInfo, type RawAsset, type SideMeta, type StageAResult } from "./stage-a";

export interface CatalogStore {
  upsertMany(entries: readonly CatalogEntry[]): Promise<void>;
  getMany(ids: readonly string[]): Promise<CatalogEntry[]>;
  /** page through one status (cursor = last id) */
  listByStatus(status: CatalogStatus, cursor: string | null, limit: number): Promise<CatalogEntry[]>;
  setStatus(id: string, status: CatalogStatus, reason: string | null, by: string): Promise<CatalogEntry | null>;
}
export function createMemoryCatalogStore(): CatalogStore & { all(): CatalogEntry[] } {
  const m = new Map<string, CatalogEntry>();
  return {
    async upsertMany(es) { for (const e of es) m.set(e.id, e); },
    async getMany(ids) { return ids.map((i) => m.get(i)).filter((x): x is CatalogEntry => !!x); },
    async listByStatus(status, cursor, limit) { return [...m.values()].filter((e) => e.status === status && (!cursor || e.id > cursor)).sort((a, b) => (a.id < b.id ? -1 : 1)).slice(0, limit); },
    async setStatus(id, status, reason) { const e = m.get(id); if (!e) return null; const n = { ...e, status, statusReason: reason }; m.set(id, n); return n; },
    all: () => [...m.values()],
  };
}

export type IngestInput = { raw: RawAsset; side?: SideMeta; measured?: Measured };
export type IngestReport = {
  rows: number; entries: number; invalid: number; coverage: Record<"full" | "partial" | "none", number>;
  byKind: Record<string, { rows: number; full: number; partial: number; none: number }>;
  status: Record<string, number>; flags: Record<string, number>; gaps: Record<string, number>; dedupe: DedupeReport; errors: { id: string; error: string }[];
};

export async function ingestRows(rows: readonly IngestInput[], ctx: { profiles: readonly AssetProfile[]; packs?: Readonly<Record<string, PackInfo>>; now: string; filters?: readonly ContentFilter[]; store?: CatalogStore; index?: CatalogIndex }): Promise<{ entries: CatalogEntry[]; report: IngestReport }> {
  const results: StageAResult[] = [];
  const errors: { id: string; error: string }[] = [];
  for (const r of rows) {
    const a = enrichStageA(r.raw, { profiles: ctx.profiles, packs: ctx.packs, now: ctx.now }, r.side, r.measured);
    results.push(a);
    if (!a.entry && errors.length < 50) errors.push({ id: r.raw.id, error: a.errors.map((e) => `${e.path}: ${e.message}`).join("; ").slice(0, 300) });
  }
  const valid = results.map((r) => r.entry).filter((e): e is CatalogEntry => !!e);
  const d = dedupe(valid);
  const out: CatalogEntry[] = [];
  for (const e of d.entries) {
    const fctx: FilterContext = { strict: e.licence.tier === "user-contributed" };
    out.push(applyDecision(e, await runContentFilters(e, fctx, ctx.filters)));
  }
  if (ctx.store) await ctx.store.upsertMany(out);
  if (ctx.index) await ctx.index.upsert(out);
  const report: IngestReport = { rows: rows.length, entries: out.length, invalid: results.filter((r) => !r.entry).length, coverage: { full: 0, partial: 0, none: 0 }, byKind: {}, status: {}, flags: {}, gaps: {}, dedupe: d.report, errors };
  for (const r of results) {
    report.coverage[r.coverage]++;
    const k = r.entry?.kind ?? "invalid";
    const b = (report.byKind[k] ??= { rows: 0, full: 0, partial: 0, none: 0 });
    b.rows++; b[r.coverage]++;
    for (const g of r.gaps) report.gaps[g] = (report.gaps[g] ?? 0) + 1;
  }
  for (const e of out) { report.status[e.status] = (report.status[e.status] ?? 0) + 1; for (const f of e.flags) report.flags[f] = (report.flags[f] ?? 0) + 1; }
  return { entries: out, report };
}

/** A Cyrus user's asset joins the community library: always pending-checks first, strict filters, then published/held/removed. */
export async function contribute(input: { raw: RawAsset; side?: SideMeta; measured?: Measured; contributorId: string; provenanceSource: "user" | "ai"; derivedFrom: readonly string[]; legalClass: "user-original" | "ai-generated-for-user" }, ctx: { profiles: readonly AssetProfile[]; now: string; filters?: readonly ContentFilter[]; store?: CatalogStore; index?: CatalogIndex }): Promise<{ entry: CatalogEntry | null; errors: string[] }> {
  const a = enrichStageA({ ...input.raw, tier: "user-contributed" }, { profiles: ctx.profiles, now: ctx.now, legalClass: input.legalClass, contributedBy: input.contributorId, licenceStatus: "user-contributed under the Cyrus terms (auto-contribution, owner decision 2026-10-10)" }, input.side, input.measured);
  if (!a.entry) return { entry: null, errors: a.errors.map((e) => `${e.path}: ${e.message}`) };
  const pending: CatalogEntry = { ...a.entry, status: "pending-checks", provenance: { ...a.entry.provenance, derivedFrom: [...input.derivedFrom] } };
  const decided = applyDecision(pending, await runContentFilters(pending, { strict: true, derivedFrom: input.derivedFrom, provenanceSource: input.provenanceSource }, ctx.filters));
  if (ctx.store) await ctx.store.upsertMany([decided]);
  if (ctx.index) await ctx.index.upsert([decided]);
  return { entry: decided, errors: [] };
}

