// ebur128/astats numbers per file) + descriptors.json (scripts/cyrus/sound-descriptors.ts, also on node-2); output =
// the committed manifest (metadata + taxonomy classification + ledger, no audio) and, optionally, the owner's
// human-readable catalog report (counts per category / use case, examples, the unclassified list, naming patterns).
//   npx tsx scripts/cyrus/sound-manifest.ts <scan.json> <descriptors.json> <out manifest.json> [report.md]
import { readFileSync, writeFileSync } from "node:fs";
import { LEDGER_LICENCE_STATUS, LEDGER_PROVENANCE, soundIdFor, type LibrarySound, type SoundManifest } from "../../lib/cyrus/sound/library";
import { classify, categoryLabel, CATEGORY_IDS, TAXONOMY, USE_CASE_IDS } from "../../lib/cyrus/sound/classify";
import type { RawDescriptors } from "../../lib/cyrus/sound/descriptors";

type Scan = { tool: string; files: { file: string; bytes: number; sha256: string; codec: string; sampleRate: number; channels: number; bitRate: number; duration: number; lufs: number | null; truePeakDb: number | null; samplePeakDb: number | null; dcOffset: number | null; rmsDb: number | null }[] };

const [, , inPath, descPath, outPath, reportPath] = process.argv;
if (!inPath || !descPath || !outPath) { console.error("usage: sound-manifest.ts <scan.json> <descriptors.json> <out.json> [report.md]"); process.exit(2); }
const scan = JSON.parse(readFileSync(inPath, "utf8")) as Scan;
const desc = JSON.parse(readFileSync(descPath, "utf8")) as Record<string, RawDescriptors>;
const r3 = (v: number | null) => (v == null || !Number.isFinite(v) ? null : Math.round(v * 1000) / 1000);
const files: LibrarySound[] = scan.files
  .filter((f) => f.codec === "mp3")

