// Measure catalog v2 stage A on a READ-ONLY copy of the staged catalog (no model calls, no writes outside --out).
//   npx tsx scripts/cyrus/catalog-stage-a.ts --catalog catalog.jsonl [--side side.jsonl] [--packs packs.json]
//       [--audio audio-rows.jsonl] [--builtin] [--out report.json] [--entries entries.jsonl]
//       [--price-cheap in,out] [--price-mid in,out] [--price-top in,out]     (USD per million tokens; optional)
// Prints coverage per kind/source, the gap reasons, dedupe/groups, filter outcomes, the stage-B plan for what is
// left (calls, tokens, optional dollars) and that plan scaled linearly to 100k assets.
import { readFileSync, writeFileSync } from "node:fs";
import { minecraftAssetProfile } from "../../lib/cyrus/adapters/minecraft";
import { builtinRows, ingestRows, type IngestInput } from "../../lib/cyrus/library/v2/pipeline";
import { estimateStageB, planStageB, type Prices } from "../../lib/cyrus/library/v2/stage-b";
import type { RawAsset, SideMeta, PackInfo } from "../../lib/cyrus/library/v2/stage-a";

const arg = (k: string) => { const i = process.argv.indexOf(k); return i > 0 ? process.argv[i + 1] : undefined; };
const jsonl = <T>(p: string): T[] => readFileSync(p, "utf8").split("\n").filter(Boolean).map((l) => JSON.parse(l) as T);
const price = (k: string): Prices | null => { const v = arg(k); if (!v) return null; const [i, o] = v.split(",").map(Number); return { inputPerMTok: i, outputPerMTok: o }; };

async function main() {
  const catalog = arg("--catalog");
  if (!catalog) { console.error("usage: catalog-stage-a.ts --catalog catalog.jsonl [...]"); process.exit(2); }
  const side = new Map<string, SideMeta>();
  if (arg("--side")) for (const s of jsonl<SideMeta & { id: string }>(arg("--side")!)) side.set(s.id, s);
  const packs: Record<string, PackInfo> = arg("--packs") ? JSON.parse(readFileSync(arg("--packs")!, "utf8")) : {};
  const rows: IngestInput[] = jsonl<RawAsset>(catalog).map((raw) => ({ raw, side: side.get(raw.id) }));
  const audio: IngestInput[] = arg("--audio") ? jsonl<RawAsset>(arg("--audio")!).map((raw) => ({ raw })) : [];
  const builtin = process.argv.includes("--builtin") ? builtinRows() : [];
  const now = "2026-10-10T00:00:00Z";
  const t0 = Date.now();
  const sets: [string, IngestInput[]][] = [["staged-cc0", rows], ["sfx-names", audio], ["builtin", builtin]];
  const out: Record<string, unknown> = {};
  for (const [name, set] of sets) {
    if (!set.length) continue;
    const r = await ingestRows(set, { profiles: [minecraftAssetProfile], packs, now });
    const plan = planStageB(r.entries);
    const est = { tokens: estimateStageB(plan), cheap: estimateStageB(plan, price("--price-cheap")), mid: estimateStageB(plan, price("--price-mid")), top: estimateStageB(plan, price("--price-top")) };
    const bySource: Record<string, { rows: number; full: number }> = {};
    for (const e of r.entries) { const b = (bySource[e.provenance.source] ??= { rows: 0, full: 0 }); b.rows++; if (e.enrichment.coverage === "full") b.full++; }
    const fits: Record<string, number> = {};
    for (const e of r.entries) { const f = e.games.minecraft?.fit ?? "unknown"; fits[`${e.kind}:${f}`] = (fits[`${e.kind}:${f}`] ?? 0) + 1; }
    const q = r.entries.map((e) => e.quality.score).sort((a, b) => a - b);
    out[name] = { report: r.report, bySource, minecraftFit: fits, quality: { p10: q[Math.floor(q.length * 0.1)], median: q[Math.floor(q.length / 2)], p90: q[Math.floor(q.length * 0.9)] }, stageB: { assetsLeft: plan.assets, represented: plan.represented, batches: plan.batches.length, skippedNoThumb: plan.skippedNoThumb, estimate: est } };
    console.log(`\n== ${name}: ${r.report.rows} rows, ${r.report.entries} entries, invalid ${r.report.invalid}`);
    console.log("coverage", r.report.coverage, "share full", (r.report.coverage.full / r.report.rows).toFixed(3));
    console.log("by kind", JSON.stringify(r.report.byKind));
    console.log("by source", JSON.stringify(bySource));
    console.log("gaps", JSON.stringify(r.report.gaps));
    console.log("dedupe", JSON.stringify(r.report.dedupe), "status", JSON.stringify(r.report.status), "flags", JSON.stringify(r.report.flags));
    console.log("minecraft fit", JSON.stringify(fits));
    console.log("stage B", JSON.stringify({ left: plan.assets, represented: plan.represented, calls: est.tokens.calls, in: est.tokens.inputTokens, out: est.tokens.outputTokens }));
    if (r.report.errors.length) console.log("errors", JSON.stringify(r.report.errors.slice(0, 5)));
    if (arg("--entries") && name === "staged-cc0") writeFileSync(arg("--entries")!, r.entries.map((e) => JSON.stringify(e)).join("\n") + "\n");
  }
  out.seconds = (Date.now() - t0) / 1000;
  if (arg("--out")) writeFileSync(arg("--out")!, JSON.stringify(out, null, 1));
  console.log(`\ndone in ${out.seconds}s`);
}
main().catch((e) => { console.error(e); process.exit(1); });

