// Cyrus asset catalog v2 (lib/cyrus/library/v2): schema, stage A (deterministic enrichment) on real staged rows and
// synthesised audio / GLB fixtures, quality, per-game fit, dedupe, content filters, retrieval (memory + SQLite FTS5),
// the model-facing tool contract and its gates, ModSpec library refs, stage B planning / budget / parsing (fake
// client: no model is ever called), stage C sampling, and the golden test over 200 rows of the real staged catalog.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import path from "node:path";
import { createHash } from "node:crypto";
import { minecraftAssetProfile } from "../lib/cyrus/adapters/minecraft";
import type { AssetProfile } from "../lib/cyrus/adapters/asset-profile";
import { CatalogEntryV1Z, catalogEntryJsonSchema, validateCatalogEntry, gateKindOf, type CatalogEntry } from "../lib/cyrus/library/v2/entry";
import { canon, humanTitle, pathTokens, isControlled } from "../lib/cyrus/library/v2/vocab";
import { audioFacts, glbFacts, pngFacts, wavDecode } from "../lib/cyrus/library/v2/extract";
import { enrichStageA, type RawAsset, type Measured } from "../lib/cyrus/library/v2/stage-a";
import { catalogQuality } from "../lib/cyrus/library/v2/quality";
import { gameFit } from "../lib/cyrus/library/v2/fit";
import { dedupe, familyStem } from "../lib/cyrus/library/v2/dedupe";
import { applyDecision, defaultFilters, runContentFilters, type ContentFilter } from "../lib/cyrus/library/v2/filters";
import { createMemoryCatalogIndex, parseQuery } from "../lib/cyrus/library/v2/retrieval";
import { createSqliteCatalogIndex } from "../lib/cyrus/library/v2/sqlite-index";
import { access, catalogGet, catalogSearch, CATALOG_TOOLS, handleCatalogTool, resolveLibrarySlot, RESULT_CHAR_BUDGET, type ToolContext } from "../lib/cyrus/library/v2/tools";
import { estimateStageB, mergeTagLine, parseTagReply, planStageB, runStageB, stageBSystem, type TaggerClient } from "../lib/cyrus/library/v2/stage-b";
import { precisionByStratum, reviewRow, sampleForReview, wilson, type Verdict } from "../lib/cyrus/library/v2/stage-c";
import { builtinRows, contribute, createMemoryCatalogStore, entryAsLibraryAsset, ingestRows } from "../lib/cyrus/library/v2/pipeline";
import { validateModSpec } from "../lib/cyrus/engine-core/spec";
import { librarySounds } from "../lib/cyrus/sound/library";
import { goldenSummary, loadGoldenSample } from "./_cyrus-catalog-golden";

const NOW = "2026-10-10T00:00:00Z";
const P = [minecraftAssetProfile];
const sha = (s: string) => createHash("sha256").update(s).digest("hex");
const row = (over: Partial<RawAsset> & { path: string; kind: string }): RawAsset => ({
  id: sha(over.path), source: over.path.split("/")[0], pack: over.path.split("/")[1], format: over.path.split(".").pop() ?? "png", sizeBytes: 20000,
  tier: "cc0", licenseSpdx: "CC0-1.0", licenseUrl: "https://example.org/licence", retrievedAt: "2026-10-10", ...over,
});
const A = (r: RawAsset, side?: Parameters<typeof enrichStageA>[2], m?: Measured) => {
  const x = enrichStageA(r, { profiles: P, now: NOW }, side, m);
  assert.ok(x.entry, `stage A produced no entry: ${JSON.stringify(x.errors)}`);
  return { ...x, entry: x.entry! };
};
const pub = (e: CatalogEntry): CatalogEntry => ({ ...e, status: "published" });

// ---------- fixtures: WAV + GLB built in memory ----------
function wav(samples: Float64Array, rate = 48000, bits: 16 | 24 | 32 = 16, channels = 1, float = false): Uint8Array {
  const bps = bits / 8, n = samples.length, data = n * bps * channels;
  const b = Buffer.alloc(44 + data);
  b.write("RIFF", 0); b.writeUInt32LE(36 + data, 4); b.write("WAVE", 8); b.write("fmt ", 12); b.writeUInt32LE(16, 16);
  b.writeUInt16LE(float ? 3 : 1, 20); b.writeUInt16LE(channels, 22); b.writeUInt32LE(rate, 24); b.writeUInt32LE(rate * bps * channels, 28); b.writeUInt16LE(bps * channels, 32); b.writeUInt16LE(bits, 34);
  b.write("data", 36); b.writeUInt32LE(data, 40);
  let o = 44;
  for (let i = 0; i < n; i++) for (let c = 0; c < channels; c++) {
    const v = Math.max(-1, Math.min(1, samples[i]));
    if (float) b.writeFloatLE(v, o); else if (bits === 16) b.writeInt16LE(Math.round(v * 32767), o); else if (bits === 24) b.writeIntLE(Math.round(v * 8388607), o, 3); else b.writeInt32LE(Math.round(v * 2147483647), o);
    o += bps;
  }
  return new Uint8Array(b);
}
const tone = (sec: number, hz: number, amp: number, rate = 48000, decay = 0) => Float64Array.from({ length: Math.round(sec * rate) }, (_, i) => amp * Math.sin((2 * Math.PI * hz * i) / rate) * Math.exp(-decay * (i / rate)));
let seed = 7; const rnd = () => ((seed = (seed * 1103515245 + 12345) % 2 ** 31) / 2 ** 31) * 2 - 1;
const burst = (sec: number, rate = 48000) => Float64Array.from({ length: Math.round(sec * rate) }, (_, i) => 0.9 * rnd() * Math.exp(-30 * (i / rate)));

function glb(json: object): Uint8Array {
  let j = Buffer.from(JSON.stringify(json));
  if (j.length % 4) j = Buffer.concat([j, Buffer.alloc(4 - (j.length % 4), 0x20)]);
  const h = Buffer.alloc(20);
  h.writeUInt32LE(0x46546c67, 0); h.writeUInt32LE(2, 4); h.writeUInt32LE(20 + j.length, 8); h.writeUInt32LE(j.length, 12); h.writeUInt32LE(0x4e4f534a, 16);
  return new Uint8Array(Buffer.concat([h, j]));
}
const CRATE_GLB = glb({
  asset: { version: "2.0" }, scene: 0, scenes: [{ nodes: [0] }],
  nodes: [{ children: [1, 2] }, { mesh: 0, scale: [2, 2, 2] }, { mesh: 0, translation: [3, 0, 0] }],
  meshes: [{ primitives: [{ attributes: { POSITION: 0 }, indices: 1 }] }],
  accessors: [{ count: 24, min: [-0.5, 0, -0.5], max: [0.5, 1, 0.5] }, { count: 36 }],
  materials: [{}], skins: [], animations: [],
});

describe("CatalogEntry v1 schema", () => {
  const e = A(row({ path: "kaykit/kaykit-character-pack-adventures/arrow_bundle.glb", kind: "model", format: "glb", triangles: 280, category: "Weapons/Ranged", tags: ["arrow", "bundle", "low-poly", "stylized", "medieval"] })).entry;
  it("a stage-A entry validates and round-trips", () => {
    assert.equal(validateCatalogEntry(e).ok, true);
    assert.equal(CatalogEntryV1Z.safeParse(JSON.parse(JSON.stringify(e))).success, true);
    assert.ok(e.shortDescription.length <= 140 && e.title.length <= 80);
  });
  it("cross-field rules", () => {
    const bad = (patch: Partial<CatalogEntry>) => { const r = validateCatalogEntry({ ...e, ...patch }); return r.ok ? [] : r.errors.map((x) => x.code); };
    assert.ok(bad({ licence: { ...e.licence, tier: "cc-by", attribution: null } }).includes("attribution_required"));
    assert.ok(bad({ licence: { ...e.licence, tier: "user-contributed" }, legalClass: "user-original" }).includes("contributor_required"));
    assert.ok(bad({ legalClass: "game-derived" }).includes("not_library_class"));
    assert.ok(bad({ duplicateOf: e.id }).includes("self_duplicate"));
    assert.ok(bad({ status: "published", flags: ["hold:trademark"] }).includes("published_with_hold"));
  });
  it("JSON schema export carries the contract", () => {
    const js = catalogEntryJsonSchema() as { properties: Record<string, unknown>; required: string[] };
    for (const k of ["id", "kind", "title", "shortDescription", "tags", "categories", "useFor", "quality", "games", "tech", "licence", "legalClass", "status"]) assert.ok(js.properties[k], k);
    assert.ok(js.required.includes("shortDescription"));
    const file = JSON.parse(readFileSync(path.join(import.meta.dirname, "..", "lib/cyrus/library/v2/catalog-entry.v1.schema.json"), "utf8"));
    assert.deepEqual(file, JSON.parse(JSON.stringify(catalogEntryJsonSchema())), "regenerate with scripts/cyrus/catalog-schema.ts");
  });
  it("gate kinds", () => {
    assert.equal(gateKindOf("music"), "sound"); assert.equal(gateKindOf("hdri"), "texture"); assert.equal(gateKindOf("model"), "model");
  });
});

describe("vocabulary + tokenising", () => {
  it("camelCase, digits, comma metadata, plurals", () => {
    const t = pathTokens("kenney/abstract-platformer/PNG/Players/Player Blue/playerBlue_duck.png");
    assert.deepEqual(t.file, ["player", "blue", "duck"]);
    assert.ok(t.folders.includes("player"));
    const s = pathTokens("sfx/2/Ilmarinen/Ilmarinen,blacksmith,forge,hotiron,water,squelch,sizzle.wav");
    assert.ok(s.commaTags.includes("blacksmith") && s.commaTags.includes("sizzle"));
    assert.equal(canon("barrels"), "barrel"); assert.equal(canon("missiles"), "missile"); assert.equal(canon("swoosh"), "whoosh");
    assert.ok(isControlled("crate") && isControlled("low-poly"));
  });
  it("titles keep the words as written (no synonym renames)", () => {
    const t = pathTokens("kenney/ui-pack-sci-fi/PNG/Red/Default/bar_round_small_square.png");
    assert.equal(humanTitle(t.fileRaw, "x"), "Bar round square");
  });
});

describe("stage A technical facts (zero tokens)", () => {
  it("GLB: triangles per instance, world bounds through node TRS, materials", () => {
    const g = glbFacts(CRATE_GLB);
    assert.ok(g.ok);
    if (!g.ok) return;
    assert.equal(g.triangles, 24); // 12 tris x 2 instances
    assert.deepEqual(g.bounds, [4, 2, 1]); // x: -1..3.5 -> wait: scaled box -1..1 and moved box 2.5..3.5 => 4.5? see below
  });
  it("GLB rejects junk", () => {
    assert.equal(glbFacts(new Uint8Array(40)).ok, false);
  });
  it("WAV 16/24/float decode + measured features", () => {
    for (const [bits, float] of [[16, false], [24, false], [32, true]] as const) {
      const d = wavDecode(wav(tone(0.5, 440, 0.5), 48000, bits, 2, float));
      assert.ok(d.ok, `bits ${bits}`);
      if (!d.ok) continue;
      assert.equal(d.channels, 2); assert.equal(d.sampleRate, 48000); assert.equal(d.frames, 24000);
      const f = audioFacts(d.mono, d.sampleRate, d.channels, d.bitDepth);
      assert.ok(Math.abs(f.durationS - 0.5) < 0.01 && f.peakDb < -5 && f.peakDb > -7, JSON.stringify(f));
    }
    assert.equal(wavDecode(new Uint8Array(10)).ok, false);
  });
  it("PNG header facts", () => {
    const b = Buffer.alloc(33); Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]).copy(b); b.writeUInt32BE(13, 8); b.write("IHDR", 12); b.writeUInt32BE(16, 16); b.writeUInt32BE(32, 20); b[24] = 8; b[25] = 6;
    assert.deepEqual(pngFacts(new Uint8Array(b)), { ok: true, width: 16, height: 32, hasAlpha: true });
  });
});

describe("stage A enrichment", () => {
  it("a named low-poly model is fully described", () => {
    const g = glbFacts(CRATE_GLB); assert.ok(g.ok);
    const r = A(row({ path: "kenney/kenney-space-kit/crate_scifi_large.glb", kind: "model", format: "glb", category: "Props/Containers & Crates" }), { styles: ["Low Poly"], themes: ["Sci-Fi"] }, { glb: g.ok ? g : null });
    assert.equal(r.coverage, "full");
    assert.equal(r.entry.categories.primary, "props/containers");
    assert.ok(r.entry.useFor.includes("loot-container-prop") && r.entry.useFor.includes("scifi-crate-prop"), r.entry.useFor.join());
    assert.equal(r.entry.style, "low-poly");
    assert.equal(r.entry.tech.triangles, 24);
    assert.equal(r.entry.games.minecraft.fit, "no"); // no glTF -> Minecraft converter (honest)
  });
  it("an opaque tile is not claimed as described", () => {
    const r = A(row({ path: "kenney/micro-roguelike/Tiles/Colored/tile_0113.png", kind: "sprite", width: 8, height: 8, category: "2D Tile size 8 × 8" }));
    assert.notEqual(r.coverage, "full");
    assert.ok(r.gaps.includes("opaque file name"));
    assert.ok(r.needsStageB);
  });
  it("PBR set: maps from the folder listing, physical size, texture fit", () => {
    const r = A(row({ path: "ambientcg/Material/PavingStones138", kind: "texture-set", format: "jpg+pbr-maps", name: "Paving Stones 138", resolution: "2K-JPG", tags: ["paving", "stones", "grey"] }),
      { files: ["PavingStones138_2K-JPG_Color.jpg", "PavingStones138_2K-JPG_NormalGL.jpg", "PavingStones138_2K-JPG_NormalDX.jpg", "PavingStones138_2K-JPG_Roughness.jpg", "PavingStones138_2K-JPG_AmbientOcclusion.jpg", "PavingStones138.png"], physicalSizeM: 2, thumbnail: "x.png" });
    assert.deepEqual(r.entry.tech.maps, ["albedo", "ao", "normal-dx", "normal-gl", "roughness"]);
    assert.equal(r.entry.categories.primary, "material/stone");
    assert.ok(r.entry.useFor.includes("stone-wall-floor-texture"));
    assert.equal(r.entry.quality.checks.find((c) => c.id === "pbr_maps")?.status, "pass");
  });
  it("audio fixtures: measured features + filename -> category, situations, quality", () => {
    const shot = wavDecode(wav(burst(0.6))); assert.ok(shot.ok);
    const f = shot.ok ? audioFacts(shot.mono, shot.sampleRate, shot.channels, shot.bitDepth) : null;
    const g = A(row({ path: "sfx/pack-a/Gunshot - Pistol - Single 3.wav", kind: "sound", format: "wav", tier: "proprietary-nxeon", licenseUrl: null, licenceNote: "owner library", licenceUnverified: true }), undefined, { audio: f });
    assert.equal(g.entry.categories.primary, "sound/weapons");
    assert.ok(g.entry.useFor.includes("gunshot-sound"));
    assert.equal(g.entry.tech.character, "transient");
    assert.equal(g.entry.games.minecraft.fit, "good");
    assert.ok(g.entry.games.minecraft.transform.includes("ogg-mono"));
    const ui = A(row({ path: "sfx/UI Pack/UI_Click_Confirm_02.wav", kind: "sound", format: "wav" }), undefined, { audio: f });
    assert.equal(ui.entry.categories.primary, "sound/ui_alerts");
    assert.ok(ui.entry.useFor.includes("ui-click-sound"), ui.entry.useFor.join());
    const quiet = wavDecode(wav(tone(1, 200, 0.001))); assert.ok(quiet.ok);
    const q = A(row({ path: "sfx/x/Room Tone 01.wav", kind: "sound", format: "wav" }), undefined, { audio: quiet.ok ? audioFacts(quiet.mono, quiet.sampleRate, 1, 16) : null });
    assert.ok(q.entry.quality.score <= 20, "a practically silent file hard-fails");
    const music = A(row({ path: "sfx/Music Loops/Battle Theme Loop 01.wav", kind: "sound", format: "wav" }), undefined, { audio: { ...f!, durationS: 45 } });
    assert.equal(music.entry.kind, "music");
  });
  it("Soundminer-style comma metadata names describe the sound", () => {
    const r = A(row({ path: "sfx/Ilmarinen/Ilmarinen,blacksmith,forge,hotiron,water,squelch,sizzle,rough.wav", kind: "sound", format: "wav" }));
    assert.ok(r.entry.tags.includes("water") || r.entry.freeTags.includes("blacksmith"));
  });
});

describe("quality cq-1", () => {
  it("unmeasured assets cannot score above 70; hard fails cap at 20", () => {
    const base = { licenceDocumented: true as const, hasThumbnail: true, metadataConfidence: 0.9 };
    const none = catalogQuality({ ...base, kind: "model", tech: { format: "glb", bytes: 0 } });
    assert.ok(none.score <= 70 && none.measured < 1);
    const zero = catalogQuality({ ...base, kind: "model", tech: { format: "glb", bytes: 1000, triangles: 0 } });
    assert.ok(zero.score <= 20);
    const good = catalogQuality({ ...base, kind: "model", tech: { format: "glb", bytes: 50000, triangles: 900, materials: 2, bounds: [0.6, 0.9, 0.6] }, expectedHeightM: 1 });
    assert.ok(good.score >= 90, String(good.score));
    assert.match(good.method, /measured/);
  });
});

describe("per-game fit from the AssetProfile", () => {
  const sprite = (w: number, style: string | null) => ({ kind: "sprite" as const, style, tags: [], categories: { primary: "items/collectibles", secondary: [] }, tech: { format: "png", bytes: 100, width: w, height: w } });
  it("Minecraft: 16 px pixel art good, 256 px no (no downscaler), sound good via ogg, glTF no", () => {
    assert.equal(gameFit(sprite(16, "pixel-art"), minecraftAssetProfile)?.fit, "good");
