const pub = (e: CatalogEntry): CatalogEntry => ({ ...e, status: "published" });

// ---------- fixtures: WAV + GLB built in memory ----------
function wav(samples: Float64Array, rate = 48000, bits: 16 | 24 | 32 = 16, channels = 1, float = false): Uint8Array {
  const bps = bits / 8, n = samples.length, data = n * bps * channels;
  const b = Buffer.alloc(44 + data);
  b.write("RIFF", 0); b.writeUInt32LE(36 + data, 4); b.write("WAVE", 8); b.write("fmt ", 12); b.writeUInt32LE(16, 16);
  b.writeUInt16LE(float ? 3 : 1, 20); b.writeUInt16LE(channels, 22); b.writeUInt32LE(rate, 24); b.writeUInt32LE(rate * bps * channels, 28); b.writeUInt16LE(bps * channels, 32); b.writeUInt16LE(bits, 34);
  b.write("data", 36); b.writeUInt32LE(data, 40);
  let o = 44;
  for (let i = 0; i < n; i++) for (let c = 0; c < channels; c++) {
    const v = Math.max(-1, Math.min(1, samples[i]));
    if (float) b.writeFloatLE(v, o); else if (bits === 16) b.writeInt16LE(Math.round(v * 32767), o); else if (bits === 24) b.writeIntLE(Math.round(v * 8388607), o, 3); else b.writeInt32LE(Math.round(v * 2147483647), o);
    o += bps;
  }
  return new Uint8Array(b);
}
const tone = (sec: number, hz: number, amp: number, rate = 48000, decay = 0) => Float64Array.from({ length: Math.round(sec * rate) }, (_, i) => amp * Math.sin((2 * Math.PI * hz * i) / rate) * Math.exp(-decay * (i / rate)));
let seed = 7; const rnd = () => ((seed = (seed * 1103515245 + 12345) % 2 ** 31) / 2 ** 31) * 2 - 1;
const burst = (sec: number, rate = 48000) => Float64Array.from({ length: Math.round(sec * rate) }, (_, i) => 0.9 * rnd() * Math.exp(-30 * (i / rate)));

function glb(json: object): Uint8Array {
  let j = Buffer.from(JSON.stringify(json));
  if (j.length % 4) j = Buffer.concat([j, Buffer.alloc(4 - (j.length % 4), 0x20)]);
  const h = Buffer.alloc(20);
  h.writeUInt32LE(0x46546c67, 0); h.writeUInt32LE(2, 4); h.writeUInt32LE(20 + j.length, 8); h.writeUInt32LE(j.length, 12); h.writeUInt32LE(0x4e4f534a, 16);
