async function demoIndex(kind: "memory" | "sqlite" = "memory") {
  const g = glbFacts(CRATE_GLB); assert.ok(g.ok);
  const rows = [
    A(row({ path: "kenney/space-kit/crate_scifi.glb", kind: "model", format: "glb" }), { styles: ["Low Poly"], themes: ["Sci-Fi"], thumbnail: "t.png" }, { glb: g.ok ? g : null }).entry,
