    const text = readFileSync(path.join(import.meta.dirname, "fixtures/cyrus-catalog/stage-b-reply-sheet.txt"), "utf8") + "\nnot json\n{\"i\":2}";
    const r = parseTagReply(text);
    assert.equal(r.lines.length, 16); assert.equal(r.rejected, 1);
    const base = A(row({ path: "kenney/tiny-dungeon/Tiles/tile_0091.png", kind: "sprite", width: 16, height: 16 })).entry;
    const m = mergeTagLine(base, r.lines[0], "claude-haiku-4-5", NOW);
    assert.ok(m && m.categories.primary === "props/containers" && m.enrichment.coverage === "full");
