  });
});

describe("stage C sampling", () => {
  it("stratified, reproducible, capped; Wilson intervals; bar check", () => {
    const es = Array.from({ length: 90 }, (_, i) => A(row({ path: `kenney/p/thing_${i}.png`, kind: i % 2 ? "sprite" : "texture", width: 16, height: 16 })).entry);
    const a = sampleForReview(es, { perStratum: 10 }), b = sampleForReview(es, { perStratum: 10 });
    assert.deepEqual(a.map((e) => e.id), b.map((e) => e.id));
    assert.ok(a.length <= 10 * new Set(es.map((e) => `${e.kind}|${e.enrichment.coverage}`)).size);
    assert.equal(reviewRow(a[0]).questions.length, 5);
    const [lo, hi] = wilson(45, 50); assert.ok(lo > 0.78 && hi < 0.97);
