cd /tank/dev-worktrees/cyrus-r14; git show HEAD:prisma/schema.prisma > .catalog-measure/schema-before.prisma; cat >> prisma/schema.prisma <<'EOF'

/// Cyrus asset catalog v2 (lib/cyrus/library/v2): one row per library asset, keyed by the sha256 of its bytes.
/// `entry` is the full CatalogEntry v1 JSON (catalog-entry.v1.schema.json); the scalar columns are copies for
/// filtering. Opaque ids only (contributorId is a Cyrus contributor id, never a user id); no foreign keys.
model CyrusCatalogEntry {
  /// sha256 hex of the asset bytes
  id            String   @id
  schemaVersion Int      @default(1)
  /// model | texture-set | texture | sprite | hdri | decal | sound | music
  kind          String
  /// pending-checks | published | held | removed
  status        String   @default("pending-checks")
  /// cc0 | cc-by | proprietary-nxeon | user-contributed
  tier          String
  primaryCat    String
  quality       Int
  /// stage-a | stage-b | owner | contributor
  enrichedBy    String
  /// full | partial | none
  coverage      String
  source        String
  pack          String?
  groupKey      String?
  duplicateOf   String?
  contributorId String?
  /// lowercase text the host's search backend indexes (title, tags, situations, categories)
  searchText    String   @db.Text
  entry         Json
  statusReason  String?
  createdAt     DateTime @default(now())
  updatedAt     DateTime @updatedAt

  @@index([status, kind, tier, quality])
  @@index([coverage, enrichedBy])
  @@index([groupKey])
  @@index([contributorId])
}

/// Stage C owner / reviewer spot-check verdicts (lib/cyrus/library/v2/stage-c.ts). reviewerId is opaque.
model CyrusCatalogReview {
  id          String   @id @default(cuid())
  entryId     String
  stratum     String
  reviewerId  String
  /// { title?: bool, category?: bool, useFor?: bool, tags?: bool, fit?: bool }
  answers     Json
  corrections Json?
  createdAt   DateTime @default(now())

  @@index([entryId])
  @@index([stratum, createdAt])
}

/// Stage B tagging runs: the HARD budget ledger across runs (estimate before, real usage after). No run without a row.
model CyrusCatalogEnrichmentRun {
  id             String    @id @default(cuid())
  /// cheap | mid | top
  tier           String
  model          String
  dryRun         Boolean   @default(true)
  /// planned | running | done | budget_exhausted | error
  status         String    @default("planned")
  assets         Int       @default(0)
  calls          Int       @default(0)
  estInputTokens Int       @default(0)
  estOutputTokens Int      @default(0)
  maxInputTokens Int       @default(0)
  maxOutputTokens Int      @default(0)
  inputTokens    Int       @default(0)
  outputTokens   Int       @default(0)
  /// who approved a non-dry run (opaque admin id); null = never approved, so never run
  approvedBy     String?
  note           String?
  createdAt      DateTime  @default(now())
  finishedAt     DateTime?

  @@index([status, createdAt])
}
EOF
